90	static ge::graphStatus ConvertContextToParamsPFA(gert::TilingContext *context,
91	                                                 ContextParamsForPFATiling &contextKeyParams,
92	                                                 bool isMaxWorkspace)
93	                                                 {
94	  contextKeyParams.opName = context->GetNodeName();
95	
96	  contextKeyParams.isKvContinuous = 1;
97	  contextKeyParams.emptyTensor = 0;
98	  contextKeyParams.fromFused = FROM_FUSED_FLAG;
99	  contextKeyParams.maxKVs = 0;
100	  contextKeyParams.attentionMask = context->GetOptionalInputTensor(ATTEN_MASK_INDEX);
101	  OP_CHECK_IF((contextKeyParams.attentionMask != nullptr) &&
102	                  (context->GetOptionalInputDesc(ATTEN_MASK_INDEX)->GetDataType() != ge::DT_BOOL) &&
103	                  (context->GetOptionalInputDesc(ATTEN_MASK_INDEX)->GetDataType() != ge::DT_INT8) &&
104	                  (context->GetOptionalInputDesc(ATTEN_MASK_INDEX)->GetDataType() != ge::DT_UINT8),
105	              OPS_REPORT_VECTOR_INNER_ERR(
106	                  context->GetNodeName(),
107	                  "Invalid attention mask datatype(%s)! Only support BOOL, INT8 and UINT8",
108	                  v2::GetPfaDataTypeStr(context->GetOptionalInputDesc(ATTEN_MASK_INDEX)->GetDataType()).c_str()),
109	              return ge::GRAPH_FAILED);
110	  contextKeyParams.actualSequenceLengthQ = context->GetOptionalInputTensor(ACTUAL_SEQ_Q_INDEX);
111	  contextKeyParams.actualSequenceLengthKV = context->GetOptionalInputTensor(ACTUAL_SEQ_KV_INDEX);
112	  OP_CHECK_IF(
113	      (contextKeyParams.actualSequenceLengthQ != nullptr) &&
114	          (context->GetOptionalInputDesc(ACTUAL_SEQ_Q_INDEX)->GetDataType() != ge::DT_INT64),
115	      OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Invalid actual_seq_lengths datatype, only support INT64"),
116	      return ge::GRAPH_FAILED);
117	  OP_CHECK_IF(
118	      (contextKeyParams.actualSequenceLengthKV != nullptr) &&
119	          (context->GetOptionalInputDesc(ACTUAL_SEQ_KV_INDEX)->GetDataType() != ge::DT_INT64),
120	      OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Invalid actual_seq_lengths_kv datatype, only support INT64"),
121	      return ge::GRAPH_FAILED);
122	  contextKeyParams.blockTable = context->GetOptionalInputTensor(BLOCK_TABLE_INDEX);
123	  contextKeyParams.inputDataType = context->GetInputDesc(QUERY_INDEX)->GetDataType();
124	  contextKeyParams.kDataType = context->GetInputDesc(KEY_INDEX)->GetDataType();
125	  contextKeyParams.vDataType = context->GetInputDesc(VALUE_INDEX)->GetDataType();
126	  contextKeyParams.maskDataType = (contextKeyParams.attentionMask != nullptr)
127	                                      ? context->GetOptionalInputDesc(ATTEN_MASK_INDEX)->GetDataType()
128	                                      : contextKeyParams.inputDataType;
129	  contextKeyParams.blockTableType = (context->GetOptionalInputDesc(BLOCK_TABLE_INDEX) != nullptr)
130	                                        ? context->GetOptionalInputDesc(BLOCK_TABLE_INDEX)->GetDataType()
131	                                        : ge::DT_INT32;
132	  contextKeyParams.outputDataType = context->GetOutputDesc(ATTENTION_OUT_INDEX)->GetDataType();
133	  contextKeyParams.queryInputShape = context->GetInputShape(QUERY_INDEX);
134	  contextKeyParams.keyInputShape = context->GetDynamicInputShape(KEY_INDEX, 0);
135	  contextKeyParams.valueInputShape = context->GetDynamicInputShape(VALUE_INDEX, 0);
136	  contextKeyParams.attentionMaskShape = context->GetOptionalInputShape(ATTEN_MASK_INDEX);
137	  contextKeyParams.blockTableShape = context->GetOptionalInputShape(BLOCK_TABLE_INDEX);
138	  contextKeyParams.outputShape = context->GetOutputShape(ATTENTION_OUT_INDEX);
139	  contextKeyParams.lseoutputShape = context->GetOutputShape(SOFTMAX_LSE_INDEX);
140	
141	  auto attrs = context->GetAttrs();
142	  OP_CHECK_IF(attrs == nullptr,
143	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Attributes returned from context is a nullptr"),
144	              return ge::GRAPH_FAILED);
145	  contextKeyParams.innerPrecisePtr = attrs->GetAttrPointer<int64_t>(ATTR_INNER_PRECISE_INDEX);
146	  contextKeyParams.headsNumber = attrs->GetAttrPointer<int32_t>(ATTR_N_INDEX);
147	  contextKeyParams.sparseMode = attrs->GetAttrPointer<int32_t>(ATTR_SPARSE_MODE_INDEX);
148	  contextKeyParams.preToken = attrs->GetAttrPointer<int64_t>(ATTR_PRE_TOKEN_INDEX);
149	  contextKeyParams.nextToken = attrs->GetAttrPointer<int64_t>(ATTR_NEXT_TOKEN_INDEX);
150	  contextKeyParams.scaleValue = attrs->GetAttrPointer<float>(ATTR_SCALE_INDEX);
151	  contextKeyParams.layout = attrs->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX);
152	  contextKeyParams.numKeyValueHeads = attrs->GetAttrPointer<int32_t>(ATTR_NUM_KV_HEADS_INDEX);
153	  contextKeyParams.blockSize = attrs->GetAttrPointer<int32_t>(ATTR_BLOCK_SIZE_INDEX);
154	  contextKeyParams.workspaceSize = context->GetWorkspaceSizes(1);
155	  contextKeyParams.isBSNDOut = 0;
156	  contextKeyParams.transposeLayout = GetTransposeLayoutPionner(string(contextKeyParams.layout));
157	  contextKeyParams.softmaxLseFlag = attrs->GetAttrPointer<bool>(SOFTMAX_LSE_FLAG_INDEX);
158	  contextKeyParams.isSoftMaxLseEnable =
159	      (contextKeyParams.softmaxLseFlag == nullptr) ? false : *contextKeyParams.softmaxLseFlag;
160	  contextKeyParams.queryRopeInputShape = context->GetOptionalInputShape(QUERY_ROPE_INDEX);
161	  contextKeyParams.qRopeDataType = (contextKeyParams.queryRopeInputShape != nullptr)
162	                                       ? context->GetOptionalInputDesc(QUERY_ROPE_INDEX)->GetDataType()
163	                                       : contextKeyParams.inputDataType;
164	  contextKeyParams.keyRopeInputShape = context->GetOptionalInputShape(KEY_ROPE_INDEX);
165	  contextKeyParams.kRopeDataType = (contextKeyParams.keyRopeInputShape != nullptr)
166	                                       ? context->GetOptionalInputDesc(KEY_ROPE_INDEX)->GetDataType()
167	                                       : contextKeyParams.kDataType;
168	  contextKeyParams.kSink = context->GetOptionalInputTensor(KEY_SINK_INDEX);
169	  contextKeyParams.kRopeSink = context->GetOptionalInputTensor(KEY_ROPE_SINK_INDEX);
170	  contextKeyParams.vSink = context->GetOptionalInputTensor(VALUE_SINK_INDEX);
171	  contextKeyParams.keySinkInputShape = context->GetOptionalInputShape(KEY_SINK_INDEX);
172	  contextKeyParams.keyRopeSinkInputShape = context->GetOptionalInputShape(KEY_ROPE_SINK_INDEX);
173	  contextKeyParams.valueSinkInputShape = context->GetOptionalInputShape(VALUE_SINK_INDEX);
174	  auto keyStrideInput = context->GetInputStride(KEY_INDEX);
175	  contextKeyParams.keyNoContinuesStride =
176	      (keyStrideInput != nullptr && keyStrideInput->GetDimNum() != 0) ? keyStrideInput->GetStride(0) : 0;
177	  auto keyRopeNoContinuesStrideInput = context->GetOptionalInputStride(KEY_ROPE_INDEX);
178	  contextKeyParams.keyRopeNoContinuesStride =
179	      (keyRopeNoContinuesStrideInput != nullptr && keyRopeNoContinuesStrideInput->GetDimNum() != 0)
180	          ? keyRopeNoContinuesStrideInput->GetStride(0)
181	          : 0;
182	
183	  const string layoutStr = string(contextKeyParams.layout);
184	  // TND/TND_NTD: use actual_seq_lengths shape size to determine batch
185	  const gert::Tensor *actSeqLenData = contextKeyParams.actualSequenceLengthQ;
186	
187	  OP_CHECK_IF(contextKeyParams.workspaceSize == nullptr,
188	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "WorkSpaceSize is nullptr"),
189	              return ge::GRAPH_FAILED);
190	
191	  // Unsupported feature checks: PSE, leftpadding, prefix, quant
192	  constexpr uint32_t PSE_SHIFT_INPUT_INDEX = 3;
193	  constexpr uint32_t QUERY_PADDING_SIZE_INPUT_INDEX = 15;
194	  constexpr uint32_t KV_PADDING_SIZE_INPUT_INDEX = 16;
195	  constexpr uint32_t KEY_SHARED_PREFIX_INPUT_INDEX = 21;
196	  constexpr uint32_t VALUE_SHARED_PREFIX_INPUT_INDEX = 22;
197	  constexpr uint32_t QUANT_SCALE2_INPUT_INDEX = 10;
198	  constexpr uint32_t QUANT_OFFSET2_INPUT_INDEX = 11;
199	
200	  auto pseShiftShape = context->GetOptionalInputShape(PSE_SHIFT_INPUT_INDEX);
201	  OP_CHECK_IF(pseShiftShape != nullptr && pseShiftShape->GetStorageShape().GetDimNum() > 0 &&
202	                  pseShiftShape->GetStorageShape().GetShapeSize() > 0,
203	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "PSE is not supported"),
204	              return ge::GRAPH_FAILED);
205	
206	  auto queryPaddingShape = context->GetOptionalInputShape(QUERY_PADDING_SIZE_INPUT_INDEX);
207	  auto kvPaddingShape = context->GetOptionalInputShape(KV_PADDING_SIZE_INPUT_INDEX);
208	  OP_CHECK_IF((queryPaddingShape != nullptr && queryPaddingShape->GetStorageShape().GetDimNum() > 0 &&
209	               queryPaddingShape->GetStorageShape().GetShapeSize() > 0) ||
210	                  (kvPaddingShape != nullptr && kvPaddingShape->GetStorageShape().GetDimNum() > 0 &&
211	                   kvPaddingShape->GetStorageShape().GetShapeSize() > 0),
212	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Leftpadding is not supported"),
213	              return ge::GRAPH_FAILED);
214	
215	  auto keyPrefixShape = context->GetOptionalInputShape(KEY_SHARED_PREFIX_INPUT_INDEX);
216	  auto valuePrefixShape = context->GetOptionalInputShape(VALUE_SHARED_PREFIX_INPUT_INDEX);
217	  OP_CHECK_IF((keyPrefixShape != nullptr && keyPrefixShape->GetStorageShape().GetDimNum() > 0 &&
218	               keyPrefixShape->GetStorageShape().GetShapeSize() > 0) ||
219	                  (valuePrefixShape != nullptr && valuePrefixShape->GetStorageShape().GetDimNum() > 0 &&
220	                   valuePrefixShape->GetStorageShape().GetShapeSize() > 0),
221	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Prefix is not supported"),
222	              return ge::GRAPH_FAILED);
223	
224	  auto quantScale2Shape = context->GetOptionalInputShape(QUANT_SCALE2_INPUT_INDEX);
225	  auto quantOffset2Shape = context->GetOptionalInputShape(QUANT_OFFSET2_INPUT_INDEX);
226	  OP_CHECK_IF((quantScale2Shape != nullptr && quantScale2Shape->GetStorageShape().GetDimNum() > 0 &&
227	               quantScale2Shape->GetStorageShape().GetShapeSize() > 0) ||
228	                  (quantOffset2Shape != nullptr && quantOffset2Shape->GetStorageShape().GetDimNum() > 0 &&
229	                   quantOffset2Shape->GetStorageShape().GetShapeSize() > 0),
230	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "Quant is not supported"),
231	              return ge::GRAPH_FAILED);
232	
233	  // Check pse_type attribute for AlibiPse
234	  auto attrs2 = context->GetAttrs();
235	  constexpr uint32_t PSE_TYPE_ATTR_INDEX = 14;
236	  auto pseTypePtr = (attrs2 != nullptr) ? attrs2->GetAttrPointer<int64_t>(PSE_TYPE_ATTR_INDEX) : nullptr;
237	  OP_CHECK_IF(pseTypePtr != nullptr && *pseTypePtr != 0,
238	              OPS_REPORT_VECTOR_INNER_ERR(context->GetNodeName(), "PSE is not supported"),
239	              return ge::GRAPH_FAILED);
240	
241	  return ge::GRAPH_SUCCESS;
242	}
