244	static bool GetMaxWorkspaceFlag(gert::TilingContext& context) 
245	{
246	    // actual_seq_lengths and actual_seq_lengths_kv are now tensors, values are not available on host side.
247	    // Core splitting info is obtained from ai_infra_attention_pioneer_metadata operator.
248	    // Always use max workspace mode.
249	    (void)context;
250	    return true;
251	}
