260	ge::graphStatus AiInfraAttentionPioneerTilingV2::DoOpTiling() 
261	{
262	    if (context_ == nullptr) {
263	        OP_LOGE("AiInfraAttentionPioneer", "tiling context is nullptr!");
264	        return ge::GRAPH_FAILED;
265	    }
266	    
267	    bool isMaxWorkspace = GetMaxWorkspaceFlag(*context_);
268	
269	    auto tempQ = context_->GetInputShape(QUERY_INDEX);
270	    auto tempV = context_->GetDynamicInputShape(VALUE_INDEX, 0);
271	    auto tempOut = context_->GetOutputShape(ATTENTION_OUT_INDEX);
272	    auto tempLse = context_->GetOutputShape(SOFTMAX_LSE_INDEX);
273	    bool qOutEmptyTensor = false;
274	    bool enablePA = context_->GetOptionalInputTensor(BLOCK_TABLE_INDEX) != nullptr;
275	    uint32_t queryD = 1U;
276	    uint32_t valueD = 1U;
277	    OP_CHECK_IF((tempQ == nullptr),
278	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "Query input is null pointer!"),
279	        return ge::GRAPH_FAILED);
280	    OP_CHECK_IF((tempV == nullptr),
281	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "Value input is null pointer!"),
282	        return ge::GRAPH_FAILED);
283	    OP_CHECK_IF((tempOut == nullptr),
284	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "AttentionOut is null pointer!"),
285	        return ge::GRAPH_FAILED);
286	    auto attrs = context_->GetAttrs();
287	    OP_CHECK_IF((tempQ->GetStorageShape().GetShapeSize() == 0 && tempOut->GetStorageShape().GetShapeSize() != 0) ||
288	                    (tempQ->GetStorageShape().GetShapeSize() != 0 && tempOut->GetStorageShape().GetShapeSize() == 0),
289	                OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
290	                                            "query shape size is %llu byte, but attention Out shape size is %llu byte, "
291	                                            "they cannot be empty while the other is not",
292	                                            tempQ->GetStorageShape().GetShapeSize(),
293	                                            tempOut->GetStorageShape().GetShapeSize()),
294	                return ge::GRAPH_FAILED);
295	    if (tempQ->GetStorageShape().GetShapeSize() == 0 && tempOut->GetStorageShape().GetShapeSize() == 0) {
296	        qOutEmptyTensor = true;
297	    }
298	
299	    OP_CHECK_IF((tempQ->GetStorageShape().GetShapeSize() == gert::Shape::kInvalidDimValue),
300	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "Get the shape size of Query failed!"),
301	        return ge::GRAPH_FAILED);
302	    OP_CHECK_IF(attrs == nullptr,
303	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "Attributes returned from GetAttrs() is a nullptr!"),
304	        return ge::GRAPH_FAILED);
305	
306	    uint32_t tempN = *attrs->GetAttrPointer<uint32_t>(ATTR_N_INDEX);
307	    uint32_t tempKVN = *attrs->GetAttrPointer<uint32_t>(ATTR_NUM_KV_HEADS_INDEX);
308	    OP_CHECK_IF(tempN == 0, OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "Q numhead is 0!"), 
309	        return ge::GRAPH_FAILED);
310	    if (tempKVN == 0U) {
311	        tempKVN = tempN;
312	    }
313	    if (enablePA) {
314	        size_t vDim = tempV->GetStorageShape().GetDimNum();
315	        if (static_cast<size_t>(vDim) == 3U) {         // BBH, dim num: 3
316	            valueD = tempV->GetStorageShape().GetDim(VALUE_DIM_2) / tempKVN;
317	        } else if (static_cast<size_t>(vDim) == 5U) {  // BND1BD0, dum num: 5
318	            valueD = tempV->GetStorageShape().GetDim(VALUE_DIM_2) * tempV->GetStorageShape().GetDim(VALUE_DIM_4);
319	        } else {
320	            /* valueD retains default from GetAttrPointer initialization */
321	        }
322	    }
323	    const string inputLayoutStr = string(attrs->GetAttrPointer<char>(ATTR_INPUT_LAYOUT_INDEX));
324	    int64_t t = 0;
325	    bool lseFlag = *attrs->GetAttrPointer<bool>(SOFTMAX_LSE_FLAG_INDEX);
326	    // Only TND and TND_NTD are supported
327	    if (inputLayoutStr == "TND" || inputLayoutStr == "TND_NTD") {
328	        t = tempQ->GetStorageShape().GetDim(QUERY_DIM_0);
329	    } else {
330	        OP_LOGE(context_->GetNodeName(), "Invalid input layout:%s. Only TND and TND_NTD are supported!",
331	            inputLayoutStr.c_str());
332	        return ge::GRAPH_FAILED;
333	    }
334	    OP_CHECK_IF((tempQ->GetStorageShape().GetDimNum() != QUERY_DIM_3),
335	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
336	            "The current layout is %s, input query shape dim(%zu) should be 3!", inputLayoutStr.c_str(),
337	            tempQ->GetStorageShape().GetDimNum()), return ge::GRAPH_FAILED);
338	    OP_CHECK_IF((tempOut->GetStorageShape().GetDimNum() != QUERY_DIM_3),
339	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
340	            "The current layout is %s, attention out shape dim(%zu) should be 3!", inputLayoutStr.c_str(),
341	            tempOut->GetStorageShape().GetDimNum()), return ge::GRAPH_FAILED);
342	    queryD = tempQ->GetStorageShape().GetDim(QUERY_DIM_2);
343	    valueD = enablePA ? valueD : tempV->GetStorageShape().GetDim(VALUE_DIM_2);
344	    if (inputLayoutStr == "TND") {
345	      OP_CHECK_IF(((queryD == valueD) && (tempQ->GetStorageShape() != tempOut->GetStorageShape())),
346	                  OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
347	                                              "Layout is TND and Query shape size[%ld, %ld, %ld] does NOT match "
348	                                              "Attention Out shape size[%ld, %ld, %ld]!",
349	                                              tempQ->GetStorageShape().GetDim(0),
350	                                              tempQ->GetStorageShape().GetDim(1),
351	                                              tempQ->GetStorageShape().GetDim(QUERY_DIM_2),
352	                                              tempOut->GetStorageShape().GetDim(0),
353	                                              tempOut->GetStorageShape().GetDim(1),
354	                                              tempOut->GetStorageShape().GetDim(OUT_DIM_2)),
355	                  return ge::GRAPH_FAILED);
356	    } else {
357	      OP_CHECK_IF(((queryD == valueD) &&
358	                   ((tempQ->GetStorageShape().GetDim(0) != tempOut->GetStorageShape().GetDim(1)) ||
359	                    (tempQ->GetStorageShape().GetDim(1) != tempOut->GetStorageShape().GetDim(0)) ||
360	                    (tempQ->GetStorageShape().GetDim(QUERY_DIM_2) != tempOut->GetStorageShape().GetDim(QUERY_DIM_2)))),
361	                  OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
362	                                              "Layout is TND_NTD and Query shape size[%ld, %ld, %ld] does NOT match "
363	                                              "Attention Out shape size[%ld, %ld, %ld]!",
364	                                              tempQ->GetStorageShape().GetDim(0),
365	                                              tempQ->GetStorageShape().GetDim(1),
366	                                              tempQ->GetStorageShape().GetDim(QUERY_DIM_2),
367	                                              tempOut->GetStorageShape().GetDim(0),
368	                                              tempOut->GetStorageShape().GetDim(1),
369	                                              tempOut->GetStorageShape().GetDim(OUT_DIM_2)),
370	                  return ge::GRAPH_FAILED);
371	    }
372	    OP_CHECK_IF((queryD > DLIMIT),
373	                OPS_REPORT_VECTOR_INNER_ERR(
374	                    context_->GetNodeName(), "D of query should be less than or equal to 512, but d = %u!", queryD),
375	                return ge::GRAPH_FAILED);
376	    bool inputOutputIsNullPtr =
377	        (context_->GetInputDesc(QUERY_INDEX) == nullptr) || (context_->GetInputDesc(KEY_INDEX) == nullptr) ||
378	        (context_->GetInputDesc(VALUE_INDEX) == nullptr) || (context_->GetOutputDesc(ATTENTION_OUT_INDEX) == nullptr) ||
379	        (context_->GetInputShape(QUERY_INDEX) == nullptr) || (context_->GetInputShape(KEY_INDEX) == nullptr) ||
380	        (context_->GetInputShape(VALUE_INDEX) == nullptr) || (context_->GetOutputShape(ATTENTION_OUT_INDEX) == nullptr);
381	    OP_CHECK_IF(inputOutputIsNullPtr,
382	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "q, k, v or attenOut is nullptr!"),
383	        return ge::GRAPH_FAILED);
384	    auto qDType = context_->GetInputDesc(QUERY_INDEX)->GetDataType();
385	    auto kDType = context_->GetInputDesc(KEY_INDEX)->GetDataType();
386	
387	    // PFA tiling process
388	    constexpr int64_t D_ALIGN_32 = 32;
389	    constexpr int64_t D_ALIGN_16 = 16;
390	
391	    PromptFlashAiInfraAttentionPioneerTilingData pfaTilingData;
392	    PromptFlashAiInfraAttentionPioneerTilingV2 pfaTiling(context_);
393	    ContextParamsForPFATiling contextParamsForPFATiling;
394	    PromptFlashAiInfraAttentionPioneerCompileInfo tempCompileInfoPtr;
395	
396	    auto platformInfoPtr = context_->GetPlatformInfo();
397	    OP_CHECK_IF(platformInfoPtr == nullptr,
398	        OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "platformInfoPtr is null!"),
399	        return ge::GRAPH_FAILED);
400	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
401	    tempCompileInfoPtr.aivNum = ascendcPlatform.GetCoreNumAiv();
402	    tempCompileInfoPtr.aicNum = ascendcPlatform.GetCoreNumAic();
403	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, tempCompileInfoPtr.ubSize);
404	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, tempCompileInfoPtr.l1Size);
405	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, tempCompileInfoPtr.l0CSize);
406	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, tempCompileInfoPtr.l0ASize);
407	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, tempCompileInfoPtr.l0BSize);
408	    tempCompileInfoPtr.socShortName = ascendcPlatform.GetSocVersion();
409	    if (tempCompileInfoPtr.socShortName == platform_ascendc::SocVersion::ASCEND310P) {
410	        // sys workspace size default value
411	        tempCompileInfoPtr.defaultSysWorkspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();
412	    } else {
413	        tempCompileInfoPtr.defaultSysWorkspaceSize = 0U;
414	    }
415	
416	    contextParamsForPFATiling.compileInfoPtr = &tempCompileInfoPtr;
417	    auto ret = ConvertContextToParamsPFA(context_, contextParamsForPFATiling, isMaxWorkspace);
418	    if (ret != ge::GRAPH_SUCCESS) {
419	      OP_LOGE(context_->GetNodeName(), "Error occored while convert tilingContext to PFA context!");
420	      return ret;
421	    }
422	    if (lseFlag != false) {
423	      if (!pfaTiling.CheckNonEmptyShapeExceptions(
424	              contextParamsForPFATiling, contextParamsForPFATiling.lseoutputShape, "softmaxLse")) {
425	        return ge::GRAPH_FAILED;
426	      }
427	      OP_CHECK_IF(
428	          ((tempLse == nullptr)),
429	          OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "SoftmaxLse shape is null, but SoftmaxLseFlag is true!"),
430	          return ge::GRAPH_FAILED);
431	
432	      if (!qOutEmptyTensor) { // q、out为空时，lse为空则不输出，不为空则输出inf
433	        OP_CHECK_IF(((tempLse->GetStorageShape().GetDimNum() != QUERY_DIM_3)), // 3：lse shape TN1
434	                    OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
435	                                                "Layout is TND/TND_NTD SoftmaxLse shape dim should be 3, but got %zu!",
436	                                                tempLse->GetStorageShape().GetDimNum()),
437	                    return ge::GRAPH_FAILED);
438	        OP_CHECK_IF((((tempLse->GetStorageShape().GetDim(QUERY_DIM_0) != t) ||
439	                      (tempLse->GetStorageShape().GetDim(QUERY_DIM_1) != tempN) ||
440	                      (tempLse->GetStorageShape().GetDim(QUERY_DIM_2) != 1))),
441	                    OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
442	                                                "SoftmaxLse shape size[%ld, %ld, %ld] does not match TN1[%ld, %u, 1]!",
443	                                                tempLse->GetStorageShape().GetDim(QUERY_DIM_0),
444	                                                tempLse->GetStorageShape().GetDim(QUERY_DIM_1),
445	                                                tempLse->GetStorageShape().GetDim(QUERY_DIM_2),
446	                                                t,
447	                                                tempN),
448	                    return ge::GRAPH_FAILED);
449	      }
450	    }
451	    if (ascendcPlatform.GetCurNpuArch() != NpuArch::DAV_3510) {
452	      OP_CHECK_IF((((contextParamsForPFATiling.inputDataType == ge::DT_INT8) ||
453	                    (contextParamsForPFATiling.kDataType == ge::DT_INT8) ||
454	                    (contextParamsForPFATiling.outputDataType == ge::DT_INT8)) &&
455	                   (queryD % D_ALIGN_32 != 0)),
456	                  OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(),
457	                                              "D(%u) of query should be 32 elements aligned when int8 is involved!",
458	                                              queryD),
459	                  return ge::GRAPH_FAILED);
460	      OP_CHECK_IF((queryD % D_ALIGN_16 != 0),
461	                  OPS_REPORT_VECTOR_INNER_ERR(
462	                      context_->GetNodeName(), "D(%u) should be 16 elements aligned when FP16/BF16 dtype!", queryD),
463	                  return ge::GRAPH_FAILED);
464	    }
465	    ret = pfaTiling.DoSubOpTiling(pfaTilingData, contextParamsForPFATiling);
466	    OP_CHECK_IF(ret == ge::GRAPH_FAILED,
467	                OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "failed in FIA DoSubOpTiling"),
468	                return ge::GRAPH_FAILED);
469	    uint64_t gen_tilingkey = GET_TPL_TILING_KEY(static_cast<uint64_t>(pfaTiling.inOutLayoutType),
470	                                                static_cast<uint64_t>(pfaTiling.config),
471	                                                static_cast<uint64_t>(pfaTiling.pseMode),
472	                                                static_cast<uint64_t>(pfaTiling.quantMode),
473	                                                pfaTiling.hasAttenMask,
474	                                                pfaTiling.hasRope,
475	                                                pfaTiling.isPa,
476	                                                pfaTiling.isFd,
477	                                                pfaTiling.emptyTensor,
478	                                                static_cast<uint64_t>(pfaTiling.PFAMask),
479	                                                static_cast<uint64_t>(pfaTiling.pFAMatMulType),
480	                                                pfaTiling.enableKVPrefix);
481	    context_->SetTilingKey(gen_tilingkey);
482	    OP_LOGI(context_->GetNodeName(), "The new template tilingkey is %llu.", gen_tilingkey);
483	    OP_LOGI(context_->GetNodeName(),
484	            "The new template tilingkey param is inOutLayoutType: %llu, config: %llu, pseMode: %llu, quantMode: %llu, "
485	            "hasAttenMask: %llu, hasRope: %llu, isPa: %llu, isFd: %llu, emptyTensor: %llu, PFAMask: %llu, "
486	            "pFAMatMulType: %llu, enableKVPrefix: %llu.",
487	            static_cast<uint64_t>(pfaTiling.inOutLayoutType),
488	            static_cast<uint64_t>(pfaTiling.config),
489	            static_cast<uint64_t>(pfaTiling.pseMode),
490	            static_cast<uint64_t>(pfaTiling.quantMode),
491	            pfaTiling.hasAttenMask,
492	            pfaTiling.hasRope,
493	            pfaTiling.isPa,
494	            pfaTiling.isFd,
495	            pfaTiling.emptyTensor,
496	            static_cast<uint64_t>(pfaTiling.PFAMask),
497	            static_cast<uint64_t>(pfaTiling.pFAMatMulType),
498	            pfaTiling.enableKVPrefix);
499	    OP_LOGI(context_->GetNodeName(), "All the FIASTiling work is done.");
500	    return ret;
501	}
