638	template <typename T>
639	static auto AlignUp(T num1, T num2) -> T
640	{
641	    if (num2 == 0) {
642	        return 0;
643	    }
644	    if (num1 < 0) {
645	        return -(-num1 / num2) * num2;
646	    }
647	    return (num1 + num2 - 1) / num2 * num2;
648	}
649	
650	template <typename T>
651	static auto CeilDivision(T num1, T num2) -> T
652	{
653	    if (num2 == 0) {
654	        return 0;
655	    }
656	    return (num1 + num2 - 1) / num2;
657	}
658	
659	template <typename T>
660	static auto CalcTailSize(T num1, T num2) -> T
661	{
662	    if (num2 == 0) {
663	        return 0;
664	    }
665	    T mod = num1 % num2;
666	    return mod != 0 ? mod : num2;
667	}
668	
669	template <typename T>
670	static auto CeilDiv(const T n1, const T n2) -> T
671	{
672	    if (n1 == 0) {
673	        return 0;
674	    }
675	    return (n2 != 0) ? (((n1 - 1) / n2) + 1) : n1;
676	}
