811	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckIODataType(ContextParamsForPFATiling& contextKeyParams) 
812	{
813	    outputType = contextKeyParams.outputDataType;
814	    inputType = contextKeyParams.inputDataType;
815	
816	    std::vector<ge::DataType> allowedDtypes = {ge::DT_FLOAT16, ge::DT_BF16, ge::DT_INT8, 
817	        ge::DT_HIFLOAT8, ge::DT_FLOAT8_E4M3FN};
818	    std::vector<uint32_t> dataTypeSizeArray = {FLOAT16SIZE, BFLOAT16SIZE, INT8SIZE, FLOAT8SIZE, FLOAT8SIZE, FLOAT8SIZE};
819	
820	    auto inputTypeCheck = std::find(allowedDtypes.begin(), allowedDtypes.end(), inputType);
821	    auto outputTypeCheck = std::find(allowedDtypes.begin(), allowedDtypes.end(), outputType);
822	    if (inputTypeCheck != allowedDtypes.end()) {
823	        uint32_t inputTypeIndex = std::distance(allowedDtypes.begin(), inputTypeCheck);
824	        dataTypeSize = dataTypeSizeArray[inputTypeIndex];
825	    }
826	    maskElemSize = dataTypeSize;
827	    if (outputTypeCheck != allowedDtypes.end()) {
828	        uint32_t outputTypeIndex = std::distance(allowedDtypes.begin(), outputTypeCheck);
829	        outputDataTypeSize = dataTypeSizeArray[outputTypeIndex];
830	    }
831	
832	    if (inputType != ge::DT_FLOAT16) {
833	        OP_LOGW(contextKeyParams.opName, "innerprecise will not take effect when input type is %s!",
834	            GetPfaDataTypeStr(inputType).c_str());
