868	bool PromptFlashAiInfraAttentionPioneerTilingV2::SetShape(ContextParamsForPFATiling &contextKeyParams,
869	                                                          const gert::StorageShape *shape,
870	                                                          const std::string inputName,
871	                                                          int64_t &b,
872	                                                          int64_t &n,
873	                                                          int64_t &s,
874	                                                          int64_t &d,
875	                                                          int64_t &h,
876	                                                          int64_t &t) const 
877	{
878	  // PA scenario: key/value shapes can be 3D(BBH), 4D(BNBD), or 5D(NZ)
879	  if (enablePA && (inputName != "query")) {
880	    if (shape->GetShape().GetDimNum() == 3) {
881	      b = shape->GetShape().GetDim(0);
882	      s = shape->GetShape().GetDim(1);
883	      h = shape->GetShape().GetDim(2);
884	      n = static_cast<int64_t>(*contextKeyParams.numKeyValueHeads);
885	      n = n > 0 ? n : static_cast<int64_t>(*contextKeyParams.headsNumber);
886	      d = n > 0 ? h / n : 0;
887	    } else if (shape->GetShape().GetDimNum() == 4) {
888	      b = shape->GetShape().GetDim(0);
889	      n = shape->GetShape().GetDim(1);
890	      s = shape->GetShape().GetDim(2);
891	      d = shape->GetShape().GetDim(3);
892	      h = n * d;
893	    } else {
894	      b = shape->GetShape().GetDim(0);
895	      n = shape->GetShape().GetDim(1);
896	      s = shape->GetShape().GetDim(3);
897	      d = shape->GetShape().GetDim(2) * shape->GetShape().GetDim(4);
898	      h = n * d;
899	    }
900	    return true;
901	  }
902	
903	  // TND layout (only supported layout)
904	  (void)inputName;
905	  b = static_cast<int64_t>(contextKeyParams.actualSequenceLengthQ->GetShapeSize());
906	  s = shape->GetStorageShape().GetDim(0);
907	  t = shape->GetStorageShape().GetDim(0);
908	  n = shape->GetStorageShape().GetDim(1);
909	  d = shape->GetStorageShape().GetDim(2);
910	  h = n * d;
911	  return true;
912	}
