1116	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckQueryOutParamsConsistency(
1117	    const ContextParamsForPFATiling &contextKeyParams,
1118	    const gert::StorageShape *queryShape,
1119	    const gert::StorageShape *outShape) const 
1120	{
1121	  const size_t queryDimNum = queryShape->GetStorageShape().GetDimNum();
1122	  const size_t outDimNum = outShape->GetStorageShape().GetDimNum();
1123	  int64_t tmpqueryDim = 0;
1124	  int64_t outDim = 0;
1125	  std::string layoutStr(contextKeyParams.layout);
1126	  OP_CHECK_IF(queryDimNum != outDimNum,
1127	              OPS_REPORT_VECTOR_INNER_ERR(
1128	                  contextKeyParams.opName,
1129	                  "tensor query shape dimNum(%zu) must be consistent with tensor output shape dimNum(%zu)!",
1130	                  queryDimNum,
1131	                  outDimNum),
1132	              return false);
1133	  OP_CHECK_IF((queryDimNum < INPUT_QKV_SHAPE_MIN_DIMS) || (queryDimNum > INPUT_QKV_SHAPE_MAX_DIMS),
1134	              OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
1135	                                          "tensor query shape dimNum(%zu) is invalid! Only support range [%u, %u].",
1136	                                          queryDimNum,
1137	                                          INPUT_QKV_SHAPE_MIN_DIMS,
1138	                                          INPUT_QKV_SHAPE_MAX_DIMS),
1139	              return false);
1140	
1141	  for (uint32_t i = 0; i < queryDimNum; ++i) {
1142	    if ((i == queryDimNum - 1) && enablePFAMLA) {
1143	      continue;
1144	    }
1145	    GetQueryDimAndOutDim(queryShape, outShape, layoutStr, tmpqueryDim, outDim, i);
1146	    OP_CHECK_IF(!isQKVDDifferent && (tmpqueryDim != outDim),
1147	                OPS_REPORT_VECTOR_INNER_ERR(
1148	                    contextKeyParams.opName,
1149	                    "tensor query shape (%ld) do not equal to tensor output shape(%ld) in dim %u for %s.",
1150	                    tmpqueryDim,
1151	                    outDim,
1152	                    i,
1153	                    layoutStr.c_str()),
1154	                return false);
1155	
1156	    OP_CHECK_IF(isQKVDDifferent && (i != queryDimNum - 1) && (tmpqueryDim != outDim),
1157	                OPS_REPORT_VECTOR_INNER_ERR(
1158	                    contextKeyParams.opName,
1159	                    "tensor query shape (%ld) do not equal to tensor output shape(%ld) in dim %u for %s.",
1160	                    tmpqueryDim,
1161	                    outDim,
1162	                    i,
1163	                    layoutStr.c_str()),
1164	                return false);
1165	  }
1166	  return true;
1167	}
