1260	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckInputDimAndHeadNum(ContextParamsForPFATiling& contextKeyParams,
1261	    const uint32_t nQAttr, const uint32_t nKVAttr) 
1262	{
1263	    uint32_t nQ = nQAttr;
1264	    uint32_t nKV = nKVAttr;
1265	    if (nKVAttr == 0U) { // Detected that nKVAttr is the default value, which means that the customer did not pass in.
1266	        nKV = nQAttr;
1267	    }
1268	
1269	    const gert::StorageShape* queryShape = contextKeyParams.queryInputShape;
1270	    const gert::StorageShape* keyShape = contextKeyParams.keyInputShape;
1271	    const gert::StorageShape* valueShape = contextKeyParams.valueInputShape;
1272	    uint32_t queryShapeHeadNum = nQ;
1273	    uint32_t keyShapeHeadNum = nKV;
1274	    uint32_t valueShapeHeadNum = nKV;
1275	    const size_t queryDim = queryShape->GetStorageShape().GetDimNum();
1276	    const size_t keyDim = keyShape->GetShape().GetDimNum();
1277	    const size_t valueDim = valueShape->GetShape().GetDimNum();
1278	    const size_t nIdx = (inputLayout == InputLayout::BNSD || inputLayout == InputLayout::TND) ? 1U : // BNSD/TND: 1
1279	        (inputLayout == InputLayout::BSND) ? 2U : 0U; //  BSND:2; NTD:0
1280	
1281	    if (((inputLayout == InputLayout::BNSD) || (inputLayout == InputLayout::BSND)) && (!enablePA)) {
1282	      if ((static_cast<size_t>(queryDim) == 4U) && (static_cast<size_t>(keyDim) == 4U) &&
1283	          (static_cast<size_t>(valueDim) == 4U)) { // dim num: 4
1284	        queryShapeHeadNum = queryShape->GetStorageShape().GetDim(nIdx);
1285	        keyShapeHeadNum = keyShape->GetShape().GetDim(nIdx);
1286	        valueShapeHeadNum = valueShape->GetShape().GetDim(nIdx);
1287	      } else {
1288	        OP_LOGE(contextKeyParams.opName,
1289	                "input dim of q(%zu), k(%zu), v(%zu) must be 4 for BNSD or BSND format!",
1290	                queryDim,
1291	                keyDim,
1292	                valueDim);
1293	        return false;
1294	      }
1295	    } else if ((inputLayout == InputLayout::TND) && (!enablePA)) {
1296	      if ((static_cast<size_t>(queryDim) == 3U) && (static_cast<size_t>(keyDim) == 3U) &&
1297	          (static_cast<size_t>(valueDim) == 3U)) { // dim num: 3
1298	        queryShapeHeadNum = queryShape->GetStorageShape().GetDim(nIdx);
1299	        keyShapeHeadNum = keyShape->GetShape().GetDim(nIdx);
1300	        valueShapeHeadNum = valueShape->GetShape().GetDim(nIdx);
1301	      } else {
1302	        OP_LOGE(contextKeyParams.opName,
1303	                "input dim of q(%zu), k(%zu), v(%zu) must be 3 for TND format!",
1304	                queryDim,
1305	                keyDim,
1306	                valueDim);
1307	        return false;
1308	      }
1309	    } else if ((inputLayout == InputLayout::NTD) && (!enablePA)) {
1310	      if ((static_cast<size_t>(queryDim) == 3U) && (static_cast<size_t>(keyDim) == 3U) &&
1311	          (static_cast<size_t>(valueDim) == 3U)) { // dim num: 3
1312	        queryShapeHeadNum = queryShape->GetStorageShape().GetDim(nIdx);
1313	        keyShapeHeadNum = keyShape->GetShape().GetDim(nIdx);
1314	        valueShapeHeadNum = valueShape->GetShape().GetDim(nIdx);
1315	      } else {
1316	        OP_LOGE(contextKeyParams.opName,
1317	                "input dim of q(%zu), k(%zu), v(%zu) must be 3 for NTD format!",
1318	                queryDim,
1319	                keyDim,
1320	                valueDim);
1321	        return false;
1322	      }
1323	    }
1324	
1325	    OP_CHECK_IF(queryShapeHeadNum != nQ,
1326	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
1327	            "numHeads(%u) in query shape must be equal to numHeads(%u) in attr!", queryShapeHeadNum, nQ),
1328	        return false);
1329	    OP_CHECK_IF(keyShapeHeadNum != nKV,
1330	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
1331	            "numHeads(%u) in key shape do not match numKeyValueHeads(%u) in attr!", keyShapeHeadNum, nKV),
1332	        return false);
1333	    OP_CHECK_IF(valueShapeHeadNum != nKV,
1334	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
1335	            "numHeads(%u) in value shape do not match numKeyValueHeads(%u) in attr!", valueShapeHeadNum, nKV),
1336	        return false);
1337	    if (enableIFAMLA || enableIFA) {
1338	        gSize = nQ / nKV;
1339	    }
1340	    return true;
1341	}
