1343	bool PromptFlashAiInfraAttentionPioneerTilingV2::SetAndCheckHeadNumRatio(
1344	    ContextParamsForPFATiling &contextKeyParams, PromptFlashAiInfraAttentionPioneerTilingData &tilingData) 
1345	{
1346	  const int32_t nQ = *contextKeyParams.headsNumber;
1347	  const int32_t nKV = *contextKeyParams.numKeyValueHeads;
1348	
1349	  if ((nQ < 0) || (nKV < 0)) {
1350	    OP_LOGE(contextKeyParams.opName, "numHeads(%d) or numKeyValueHeads(%d) is negative!", nQ, nKV);
1351	    return false;
1352	  }
1353	
1354	  if (!CheckInputDimAndHeadNum(contextKeyParams, nQ, nKV)) {
1355	    return false;
1356	  }
1357	
1358	  if (nKV == 0) { // Detected that nKV is the default value, which means that the customer did not pass in.
1359	    tilingData.promptAttentionBaseParams.set_headNumRatio(1);
1360	    tilingData.promptAttentionBaseParams.set_gOfMla(1);
1361	    return true;
1362	  }
1363	
1364	  if (nQ % nKV != 0) {
1365	    OP_LOGE(contextKeyParams.opName, "numHeads(%d) must be divisible by numKeyValueHeads(%d)!", nQ, nKV);
1366	    return false;
1367	  }
1368	
1369	  if (enableIFAMLA && (nQ / nKV > GLIMIT_128)) { // G cannot be greater than 128.
1370	    OP_LOGE(contextKeyParams.opName,
1371	            "In mla decode scenario, the G(numHeads / numKeyValueHeads) connot be larger than 128, but G = %d",
1372	            nQ / nKV);
1373	    return false;
1374	  }
1375	
1376	  if (enableIFAMLA || enableIFA) {
1377	    tilingData.promptAttentionBaseParams.set_headNumRatio(1);
1378	    tilingData.promptAttentionBaseParams.set_gOfMla(gSize);
1379	  } else {
1380	    tilingData.promptAttentionBaseParams.set_headNumRatio(nQ / nKV);
1381	    tilingData.promptAttentionBaseParams.set_gOfMla(1);
1382	  }
1383	
1384	  return true;
1385	}
