1387	void PromptFlashAiInfraAttentionPioneerTilingV2::SetSparseModeData(ContextParamsForPFATiling& contextKeyParams,
1388	    const gert::StorageShape* attenMaskShape, const int32_t* sparseMode, const int64_t* preTokens,
1389	    const int64_t* nextTokens) 
1390	{
1391	    if (*preTokens > SPARSE_MODE_INT_MAX) {
1392	        sparsePreTokens = SPARSE_MODE_INT_MAX;
1393	    } else if (*preTokens < -(SPARSE_MODE_INT_MAX)) {
1394	        sparsePreTokens = -(SPARSE_MODE_INT_MAX);
1395	    } else {
1396	        sparsePreTokens = *preTokens;
1397	    }
1398	
1399	    if (*nextTokens > SPARSE_MODE_INT_MAX) {
1400	        sparseNextTokens = SPARSE_MODE_INT_MAX;
1401	    } else if (*nextTokens < -(SPARSE_MODE_INT_MAX)) {
1402	        sparseNextTokens = -(SPARSE_MODE_INT_MAX);
1403	    } else {
1404	        sparseNextTokens = *nextTokens;
1405	    }
1406	    if ((attenMaskShape != nullptr) && (sparseMode != nullptr)) {
1407	        if (*sparseMode == SPARSE_MODE_LEFT_UP) {
1408	            sparsePreTokens = SPARSE_MODE_INT_MAX;
1409	            sparseNextTokens = 0;
1410	        // Right down tokens are calculated on the kernel side.
1411	        } else if (*sparseMode == SPARSE_MODE_RIGHT_DOWN) {
1412	            sparsePreTokens = SPARSE_MODE_INT_MAX;
1413	        } else if (*sparseMode == SPARSE_MODE_ALL_MASK) {
1414	            sparsePreTokens = SPARSE_MODE_INT_MAX;
1415	            sparseNextTokens = SPARSE_MODE_INT_MAX;
1416	        } else if (*sparseMode == SPARSE_MODE_BAND) {
1417	            isBandMode = true;
1418	        }
1419	        sparseModeVal = *sparseMode;
1420	        OP_LOGI(contextKeyParams.opName, "sparseMode is %d.", sparseModeVal);
1421	    }
1422	    if ((sparseMode != nullptr) && (*sparseMode == SPARSE_MODE_NO_MASK)) {
1423	        // sparse mode need process attention mask when empty tensor scenes as same.
1424	        if (((attenMaskShape != nullptr) && (attenMaskShape->GetStorageShape().GetShapeSize() == 0)) || 
1425	            (attenMaskShape == nullptr)) {
1426	            sparsePreTokens = SPARSE_MODE_INT_MAX;
1427	            sparseNextTokens = SPARSE_MODE_INT_MAX;
1428	            sparseModeVal = *sparseMode;
1429	        }
1430	    }
1431	    if (isDefaultSparseMode && enableLeftPadding) {
1432	        // For scenes with sparse mode=0 and left padding, the attention mask part is fully calculated
1433	        sparsePreTokens = SPARSE_MODE_INT_MAX;
1434	        sparseNextTokens = SPARSE_MODE_INT_MAX;
1435	    }
1436	}
