1438	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckMaskShapeCrossSparse(ContextParamsForPFATiling& contextKeyParams,
1439	    PromptFlashAiInfraAttentionPioneerTilingData& tilingData, const int32_t* sparseMode, uint32_t sQ, const uint32_t sK,
1440	    const uint32_t batchSize) 
1441	{
1442	    const gert::StorageShape* attenMaskShape = contextKeyParams.attentionMaskShape;
1443	    size_t attenMaskDim = attenMaskShape->GetStorageShape().GetDimNum();
1444	    if (static_cast<size_t>(attenMaskDim) != 2U) {
1445	        return false;
1446	    }
1447	    int64_t attenMaskS1 = attenMaskShape->GetStorageShape().GetDim(0);
1448	    int64_t attenMaskS2 = attenMaskShape->GetStorageShape().GetDim(1);
1449	    if (attenMaskS1 != 2048 || attenMaskS2 != 2048) {
