1455	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckPFAMerge(ContextParamsForPFATiling& contextKeyParams,
1456	    const PFAShapeInfo& queryShapeInfo) const 
1457	{
1458	    const int32_t pfaMergeGSLimit = pfaMergeQsLimit * pfaMergeGLimit;
1459	
1460	    if (queryShapeInfo.s <= 1U) {
1461	        return false;
1462	    }
1463	
1464	    if (queryShapeInfo.d > 256U &&
1465	        (queryShapeInfo.d % 64) != 0) { // 256U, 64: d > 256 must be multiple of 64 for memory alignment
1466	      return false;
1467	    }
1468	
1469	    const int32_t nQ = *contextKeyParams.headsNumber;
1470	    const int32_t nKV = *contextKeyParams.numKeyValueHeads;
1471	    if ((nKV > 0) && (static_cast<uint32_t>(nQ / nKV) * queryShapeInfo.s > pfaMergeGSLimit)) {
1472	        return false;
1473	    }
1474	    if ((nKV == 0) && (queryShapeInfo.s > pfaMergeGSLimit)) {
1475	        return false;
1476	    }
1477	
1478	    // 隔离高阶特性
1479	    std::string layoutStr(contextKeyParams.layout);
1480	    bool isTransposeLayout = layoutStr == "BNSD_BSND" || layoutStr == "BSND_BNSD" || layoutStr == "BSH_BNSD" ||
1481	        layoutStr == "NTD" || layoutStr == "NTD_TND" || layoutStr == "TND_NTD";
1482	    bool hasCrossoverAttr = enableMask || enablePseShift || enablePA || enableAlibiPse || enablePFARope ||
1483	        enableLeftPadding || enableTensorList ||
1484	        contextKeyParams.isSoftMaxLseEnable || isTransposeLayout || enableLearnSink;
1485	
1486	    return !hasCrossoverAttr;
1487	}
