1489	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckIO(ContextParamsForPFATiling& contextKeyParams,
1490	    PFAShapeInfo& queryShapeInfo, PFAShapeInfo& valueShapeInfo) 
1491	{
1492	    const gert::StorageShape* queryShape = contextKeyParams.queryInputShape;
1493	    const gert::StorageShape* outShape = contextKeyParams.outputShape;
1494	    const gert::StorageShape* valueShape = contextKeyParams.valueInputShape;
1495	    // check dtype
1496	    if (!CheckIODataType(contextKeyParams)) {
1497	        return false;
1498	    }
1499	
1500	    // check layout
1501	    OP_CHECK_IF((!SetInputLayout(contextKeyParams.layout)),
1502	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, 
1503	            "Invalid input layout:%s. Only TND and TND_NTD are supported for attention pioneer.",
1504	            contextKeyParams.layout),
1505	        return false);
1506	
1507	    // check query shape size and bnsd
1508	    OP_CHECK_IF((!GetAndCheckShape(contextKeyParams, queryShapeInfo, queryShape, "query")),
1509	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check query shape failed."),
1510	        return false);
1511	    if (queryShapeInfo.s == 1) {
1512	        enableIFAMask = true;
1513	        enableIFA = true;
1514	    }
1515	    enablePFAMerge = CheckPFAMerge(contextKeyParams, queryShapeInfo);
1516	    // check value shape
1517	    if (enablePA) { // only get shape
1518	        int64_t b = 0;
1519	        int64_t n = 0;
1520	        int64_t s = 0;
1521	        int64_t d = 0;
1522	        int64_t h = 0;
1523	        int64_t t = 0;
1524	        if (!SetShape(contextKeyParams, valueShape, "value", b, n, s, d, h, t)) {
1525	            return false;
1526	        }
1527	        valueShapeInfo.d = d;
1528	    } else {
1529	        OP_CHECK_IF((!GetAndCheckShape(contextKeyParams, valueShapeInfo, valueShape, "value")),
1530	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check value shape failed."),
1531	        return false);
1532	    }
1533	    if (queryShapeInfo.d == MLA_QKD_SIZE && valueShapeInfo.d == MLA_VD_SIZE) {
1534	        enablePFAMLA = true;
1535	        enablePFAMerge = false;
1536	    }
1537	
1538	    if(queryShapeInfo.d != valueShapeInfo.d && !enablePFAMLA) {
1539	        isQKVDDifferent = true;
1540	    }
1541	    OP_CHECK_IF(
1542	        isQKVDDifferent &&
1543	            (contextKeyParams.inputDataType != ge::DT_FLOAT16 && contextKeyParams.inputDataType != ge::DT_BF16),
1544	        OPS_REPORT_VECTOR_INNER_ERR(
1545	            contextKeyParams.opName,
1546	            "Query data type must be float16 or bf16 when query and key headdim is not equal to value headdim."),
1547	        return false);
1548	    OP_CHECK_IF(
1549	        isQKVDDifferent && (outputType != ge::DT_FLOAT16 && outputType != ge::DT_BF16),
1550	        OPS_REPORT_VECTOR_INNER_ERR(
1551	            contextKeyParams.opName,
1552	            "Output data type must be float16 or bf16 when query and key headdim is not equal to value headdim."),
1553	        return false);
1554	    OP_CHECK_IF(isQKVDDifferent && (queryShapeInfo.d > 128),
1555	                OPS_REPORT_VECTOR_INNER_ERR(
1556	                    contextKeyParams.opName,
1557	                    "Query headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
1558	                return false);
1559	    OP_CHECK_IF(isQKVDDifferent && (valueShapeInfo.d > 128),
1560	                OPS_REPORT_VECTOR_INNER_ERR(
1561	                    contextKeyParams.opName,
1562	                    "Value headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
1563	                return false);
1564	    // check query and output consistency
1565	    OP_CHECK_IF((!CheckQueryOutParamsConsistency(contextKeyParams, queryShape, outShape)),
1566	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Query and output consistency check failed."),
1567	        return false);
1568	    return true;
1569	}
