1571	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckKV(ContextParamsForPFATiling& contextKeyParams,
1572	    PFAShapeInfo& keyShapeInfo, PFAShapeInfo& valueShapeInfo) 
1573	{
1574	    const gert::StorageShape* keyShape = contextKeyParams.keyInputShape;
1575	    const gert::StorageShape* valueShape = contextKeyParams.valueInputShape;
1576	
1577	    // check dtype
1578	    if (!CheckKVDataType(contextKeyParams)) {
1579	        return false;
1580	    }
1581	
1582	    // check key shape size and bnsd
1583	    OP_CHECK_IF((!enablePA && !GetAndCheckShape(contextKeyParams, keyShapeInfo, keyShape, "key")),
1584	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check key shape failed."),
1585	        return false);
1586	    
1587	    // check value shape size and bnsd
1588	    OP_CHECK_IF((!enablePA && !GetAndCheckShape(contextKeyParams, valueShapeInfo, valueShape, "value")),
1589	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check value shape failed."),
1590	        return false);
1591	
1592	    OP_CHECK_IF(isQKVDDifferent &&
1593	                    (contextKeyParams.kDataType != ge::DT_FLOAT16 && contextKeyParams.kDataType != ge::DT_BF16),
1594	                OPS_REPORT_VECTOR_INNER_ERR(
1595	                    contextKeyParams.opName,
1596	                    "Key type must must be float16 or bf16 when query and key headdim is not equal to value headdim."),
1597	                return false);
1598	    OP_CHECK_IF(
1599	        isQKVDDifferent && (contextKeyParams.vDataType != ge::DT_FLOAT16 && contextKeyParams.vDataType != ge::DT_BF16),
1600	        OPS_REPORT_VECTOR_INNER_ERR(
1601	            contextKeyParams.opName,
1602	            "Value type must must be float16 or bf16 when query and key headdim is not equal to value headdim."),
1603	        return false);
1604	    OP_CHECK_IF(isQKVDDifferent && (keyShapeInfo.d > 128),
1605	                OPS_REPORT_VECTOR_INNER_ERR(
1606	                    contextKeyParams.opName,
1607	                    "Key headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
1608	                return false);
1609	    OP_CHECK_IF(isQKVDDifferent && (valueShapeInfo.d > 128),
1610	                OPS_REPORT_VECTOR_INNER_ERR(
1611	                    contextKeyParams.opName,
1612	                    "Value headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
1613	                return false);
1614	    // check key and value consistency
1615	    OP_CHECK_IF((!CheckKeyValueParamsConsistency(contextKeyParams, keyShape, valueShape)),
1616	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Key and value consistency check failed."),
1617	        return false);
1618	
1619	    return true;
1620	}
