1634	bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckRope(ContextParamsForPFATiling& contextKeyParams,
1635	    PFAShapeInfo& queryShapeInfo, PFAShapeInfo& keyShapeInfo, PFAShapeInfo& queryRopeShapeInfo) 
1636	{
1637	    if (contextKeyParams.queryRopeInputShape == nullptr && contextKeyParams.keyRopeInputShape == nullptr) {
1638	        return true;
1639	    }
1640	    OP_CHECK_IF((contextKeyParams.queryRopeInputShape == nullptr && contextKeyParams.keyRopeInputShape != nullptr),
1641	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "queryRope is null, but keyRope is not null, "
1642	        "they should be consistent."), return false);
1643	    OP_CHECK_IF((contextKeyParams.queryRopeInputShape != nullptr && contextKeyParams.keyRopeInputShape == nullptr),
1644	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "queryRope is not null, but keyRope is null, "
1645	        "they should be consistent."), return false);
1646	    OP_CHECK_IF(!(CheckRopeDataType(contextKeyParams)),
1647	        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Check rope datatype failed."),
1648	        return false);
1649	    const gert::StorageShape* queryRopeShape = contextKeyParams.queryRopeInputShape;
1650	    const gert::StorageShape* keyRopeShape = contextKeyParams.keyRopeInputShape;
1651	
1652	    // check queryRope shape
1653	    OP_CHECK_IF((!GetAndCheckRopeShape(
1654	                    contextKeyParams, queryShapeInfo, queryRopeShapeInfo, queryRopeShape, "query", "queryRope")),
1655	                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check queryRope shape failed."),
1656	                return false);
1657	    // check keyRope shape
1658	    PFAShapeInfo keyRopeShapeInfo;
1659	    OP_CHECK_IF((!enablePA && !GetAndCheckRopeShape(
1660	                                  contextKeyParams, keyShapeInfo, keyRopeShapeInfo, keyRopeShape, "key", "keyRope")),
1661	                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check queryRope shape failed."),
1662	                return false);
1663	    enableIFA = false;
1664	    enableIFAMask = false;
1665	    enablePFAMerge = false;
1666	    if (queryShapeInfo.d == QUERY_SHAPE_DIM_D_128_TILING_V2) {
1667	        enablePFARope = true;
1668	    } else {
1669	        enableIFAMLA = true;
1670	    }
1671	    OP_LOGI(contextKeyParams.opName, "enableIFAMLA is %d, enablePA is %d, enableMask is %d, faRunFlag_ is %d", 
1672	                enableIFAMLA, enablePA, enableMask, faRunFlag_);
1673	    return true;
1674	}
