bool PromptFlashAiInfraAttentionPioneerTilingV2::SetShape(ContextParamsForPFATiling &contextKeyParams,
                                                          const gert::StorageShape *shape,
                                                          const std::string inputName,
                                                          int64_t &b,
                                                          int64_t &n,
                                                          int64_t &s,
                                                          int64_t &d,
                                                          int64_t &h,
                                                          int64_t &t) const 
{
  // PA scenario: key/value shapes can be 3D(BBH), 4D(BNBD), or 5D(NZ)
  if (enablePA && (inputName != "query")) {
    if (shape->GetShape().GetDimNum() == 3) {
      b = shape->GetShape().GetDim(0);
      s = shape->GetShape().GetDim(1);
      h = shape->GetShape().GetDim(2);
      n = static_cast<int64_t>(*contextKeyParams.numKeyValueHeads);
      n = n > 0 ? n : static_cast<int64_t>(*contextKeyParams.headsNumber);
      d = n > 0 ? h / n : 0;
    } else if (shape->GetShape().GetDimNum() == 4) {
      b = shape->GetShape().GetDim(0);
      n = shape->GetShape().GetDim(1);
      s = shape->GetShape().GetDim(2);
      d = shape->GetShape().GetDim(3);
      h = n * d;
    } else {
      b = shape->GetShape().GetDim(0);
      n = shape->GetShape().GetDim(1);
      s = shape->GetShape().GetDim(3);
      d = shape->GetShape().GetDim(2) * shape->GetShape().GetDim(4);
      h = n * d;
    }
    return true;
  }

  // TND layout (only supported layout)
  (void)inputName;
  b = static_cast<int64_t>(contextKeyParams.actualSequenceLengthQ->GetShapeSize());
  s = shape->GetStorageShape().GetDim(0);
  t = shape->GetStorageShape().GetDim(0);
  n = shape->GetStorageShape().GetDim(1);
  d = shape->GetStorageShape().GetDim(2);
  h = n * d;
  return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::GetAndCheckShape(ContextParamsForPFATiling& contextKeyParams,
    PFAShapeInfo& shapeInfo, const gert::StorageShape* shape, const std::string& sName) const
{
    OP_CHECK_IF((shape->GetStorageShape().GetDimNum() != 3),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "dim num of %s should = 3 for TND layout, "
            "but dim num is %zu.", sName.c_str(), shape->GetStorageShape().GetDimNum()), return false);

    int64_t b = 0;
    int64_t n = 0;
    int64_t s = 0;
    int64_t d = 0;
    int64_t h = 0;
    int64_t t = 0;
    if (!SetShape(contextKeyParams, shape, sName, b, n, s, d, h, t)) {
        return false;
    }
    OP_CHECK_IF((b > BLIMIT || b <= 0),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "batch size of %s should be less than or equal to %u and > 0, but batch size = %ld.",
                    sName.c_str(),
                    BLIMIT,
                    b),
                return false);
    OP_CHECK_IF((s < 0),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName, "seq size of %s should >= 0, but sequence size = %ld.", sName.c_str(), s),
                return false);
    if (s > SLIMIT) {
        OP_LOGW(contextKeyParams.opName, "sequence size of %s should <= 20M, but seq = %ld.", sName.c_str(), s);
    }
    OP_CHECK_IF((d > DLIMIT || d <= 0),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                            "d size of %s should be less than or equal to %u and > 0, but d = %ld.",
                                            sName.c_str(),
                                            DLIMIT,
                                            d),
                return false);
    OP_CHECK_IF(
        (t <= 0),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "When layout is TND, t should > 0, but t = %ld.", t),
        return false);
    shapeInfo.b = static_cast<uint32_t>(b);
    shapeInfo.n = static_cast<uint32_t>(n);
    shapeInfo.s = static_cast<uint32_t>(s);
    shapeInfo.d = static_cast<uint32_t>(d);
    shapeInfo.h = static_cast<uint32_t>(h);
    shapeInfo.t = static_cast<uint32_t>(t);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::GetAndCheckRopeShape(ContextParamsForPFATiling &contextKeyParams,
                                                                      PFAShapeInfo &shapeInfo,
                                                                      PFAShapeInfo &ropeShapeInfo,
                                                                      const gert::StorageShape *shape,
                                                                      const std::string &sName,
                                                                      const std::string &rName) const 
{
  std::string layoutStr(contextKeyParams.layout);
  OP_CHECK_IF(
      (shape->GetStorageShape().GetDimNum() != 3) &&
          (inputLayout == InputLayout::BSH || inputLayout == InputLayout::TND || inputLayout == InputLayout::NTD),
      OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                  "dim num of %s should = 3 when inputLayout is %s,"
                                  "but dim num is %zu.",
                                  sName.c_str(),
                                  layoutStr.c_str(),
                                  shape->GetStorageShape().GetDimNum()),
      return false);
  OP_CHECK_IF(
      (shape->GetStorageShape().GetDimNum() != 4) &&
          (inputLayout != InputLayout::BSH && inputLayout != InputLayout::TND && inputLayout != InputLayout::NTD),
      OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                  "dim num of %s should = 4 when inputLayout is %s,"
                                  "but dim num is %zu.",
                                  sName.c_str(),
                                  layoutStr.c_str(),
                                  shape->GetStorageShape().GetDimNum()),
      return false);

  OP_CHECK_IF((shapeInfo.d != 128 && shapeInfo.d != 512),
              OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                          "When queryRope and keyRope is not null, d size of %s must be 128 or 512, "
                                          "but d = %d.",
                                          sName.c_str(),
                                          shapeInfo.d),
              return false);

  int64_t b = 0;
  int64_t n = 0;
  int64_t s = 0;
  int64_t d = 0;
  int64_t h = 0;
  int64_t t = 0;
  if (!SetShape(contextKeyParams, shape, sName, b, n, s, d, h, t)) {
    return false;
  }

  if (inputLayout == InputLayout::BSH) {
    OP_CHECK_IF((d != 64),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                            "When queryRope and keyRope is not null, d size of %s must be 64, "
                                            "but d = %ld, and layout is BSH, d = h / headNumber.",
                                            rName.c_str(),
                                            d),
                return false);
  } else {
    OP_CHECK_IF((d != 64),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                            "When queryRope and keyRope is not null, d size of %s must be 64, "
                                            "but d = %ld.",
                                            rName.c_str(),
                                            d),
                return false);
  }

  if (!enableTensorList || sName == "query") {
    OP_CHECK_IF((b != shapeInfo.b),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "batch size of %s should be equal to %s batch size, but %s batch size = %ld, %s batch size = %u.",
                    rName.c_str(),
                    sName.c_str(),
                    rName.c_str(),
                    b,
                    sName.c_str(),
                    shapeInfo.b),
                return false);
  }
  OP_CHECK_IF((n != shapeInfo.n),
              OPS_REPORT_VECTOR_INNER_ERR(
                  contextKeyParams.opName,
                  "head number of %s should be equal to %s head number, but %s head number = %ld, %s head number = %u.",
                  rName.c_str(),
                  sName.c_str(),
                  rName.c_str(),
                  n,
                  sName.c_str(),
                  shapeInfo.n),
              return false);
  OP_CHECK_IF((s != shapeInfo.s),
              OPS_REPORT_VECTOR_INNER_ERR(
                  contextKeyParams.opName,
                  "seq length of %s should be equal to %s seq length, but %s seq length = %ld, %s seq length = %u.",
                  rName.c_str(),
                  sName.c_str(),
                  rName.c_str(),
                  s,
                  sName.c_str(),
                  shapeInfo.s),
              return false);
  OP_CHECK_IF((t != shapeInfo.t),
              OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                          "t of %s should be equal to %s t, but %s t = %ld, %s t = %u.",
                                          rName.c_str(),
                                          sName.c_str(),
                                          rName.c_str(),
                                          t,
                                          sName.c_str(),
                                          shapeInfo.t),
              return false);

  if (((inputLayout == InputLayout::BSH) || (inputLayout == InputLayout::BSND)) &&
      (static_cast<uint32_t>(h) > HLIMIT)) {
    OP_LOGW(contextKeyParams.opName,
            "layout = %s, h(%ld) size of %s should be less than or equal to 65535, "
            "which may cause precision problem! Please use BNSD or BNSD_BSND instead.",
            contextKeyParams.layout,
            h,
            sName.c_str());
  }
  ropeShapeInfo.b = static_cast<uint32_t>(b);
  ropeShapeInfo.n = static_cast<uint32_t>(n);
  ropeShapeInfo.s = static_cast<uint32_t>(s);
  ropeShapeInfo.d = static_cast<uint32_t>(d);
  ropeShapeInfo.h = static_cast<uint32_t>(h);
  ropeShapeInfo.t = static_cast<uint32_t>(t);
  return true;
}

void PromptFlashAiInfraAttentionPioneerTilingV2::GetQueryDimAndOutDim(const gert::StorageShape *queryShape,
                                                                      const gert::StorageShape *outShape,
                                                                      const std::string &layoutStr,
                                                                      int64_t &tmpqueryDim,
                                                                      int64_t &outDim,
                                                                      uint32_t i) const 
{
  // Only TND and TND_NTD layouts supported
  if (layoutStr == "TND_NTD") {
    if (i == 0) {
      tmpqueryDim = queryShape->GetStorageShape().GetDim(i);
      outDim = outShape->GetStorageShape().GetDim(i + 1);
    } else if (i == 1) {
      tmpqueryDim = queryShape->GetStorageShape().GetDim(i);
      outDim = outShape->GetStorageShape().GetDim(i - 1);
    }
  } else {
    tmpqueryDim = queryShape->GetStorageShape().GetDim(i);
    outDim = outShape->GetStorageShape().GetDim(i);
  }
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckQueryOutParamsConsistency(
    const ContextParamsForPFATiling &contextKeyParams,
    const gert::StorageShape *queryShape,
    const gert::StorageShape *outShape) const 
{
  const size_t queryDimNum = queryShape->GetStorageShape().GetDimNum();
  const size_t outDimNum = outShape->GetStorageShape().GetDimNum();
  int64_t tmpqueryDim = 0;
  int64_t outDim = 0;
  std::string layoutStr(contextKeyParams.layout);
  OP_CHECK_IF(queryDimNum != outDimNum,
              OPS_REPORT_VECTOR_INNER_ERR(
                  contextKeyParams.opName,
                  "tensor query shape dimNum(%zu) must be consistent with tensor output shape dimNum(%zu)!",
                  queryDimNum,
                  outDimNum),
              return false);
  OP_CHECK_IF((queryDimNum < INPUT_QKV_SHAPE_MIN_DIMS) || (queryDimNum > INPUT_QKV_SHAPE_MAX_DIMS),
              OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                          "tensor query shape dimNum(%zu) is invalid! Only support range [%u, %u].",
                                          queryDimNum,
                                          INPUT_QKV_SHAPE_MIN_DIMS,
                                          INPUT_QKV_SHAPE_MAX_DIMS),
              return false);

  for (uint32_t i = 0; i < queryDimNum; ++i) {
    if ((i == queryDimNum - 1) && enablePFAMLA) {
      continue;
    }
    GetQueryDimAndOutDim(queryShape, outShape, layoutStr, tmpqueryDim, outDim, i);
    OP_CHECK_IF(!isQKVDDifferent && (tmpqueryDim != outDim),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "tensor query shape (%ld) do not equal to tensor output shape(%ld) in dim %u for %s.",
                    tmpqueryDim,
                    outDim,
                    i,
                    layoutStr.c_str()),
                return false);

    OP_CHECK_IF(isQKVDDifferent && (i != queryDimNum - 1) && (tmpqueryDim != outDim),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "tensor query shape (%ld) do not equal to tensor output shape(%ld) in dim %u for %s.",
                    tmpqueryDim,
                    outDim,
                    i,
                    layoutStr.c_str()),
                return false);
  }
  return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckKVDataType(ContextParamsForPFATiling& contextKeyParams) const
{
    ge::DataType keyDataType = contextKeyParams.kDataType;
    ge::DataType valueDataType = contextKeyParams.vDataType;

    std::vector<ge::DataType> allowedDtypes = {ge::DT_FLOAT16, ge::DT_BF16, ge::DT_INT8,
        ge::DT_HIFLOAT8, ge::DT_FLOAT8_E4M3FN};

    auto keyTypeCheck = std::find(allowedDtypes.begin(), allowedDtypes.end(), keyDataType);

    OP_CHECK_IF((keyDataType != valueDataType), OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
        "DataType of key(%s) not equal datatype of value(%s).",
        GetPfaDataTypeStr(contextKeyParams.kDataType).c_str(), GetPfaDataTypeStr(contextKeyParams.vDataType).c_str()),
        return false);
    OP_CHECK_IF((keyTypeCheck == allowedDtypes.end()),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                            "DataType of key(%s) should be DT_FLOAT16, DT_BF16, DT_INT8.",
                                            GetPfaDataTypeStr(contextKeyParams.kDataType).c_str()),
                return false);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckRopeDataType(ContextParamsForPFATiling& contextKeyParams) const
{
    ge::DataType queryDataType = contextKeyParams.inputDataType;
    ge::DataType keyDataType = contextKeyParams.kDataType;
    ge::DataType queryRopeDataType = contextKeyParams.qRopeDataType;
    ge::DataType keyRopeDataType = contextKeyParams.kRopeDataType;
    OP_CHECK_IF((queryDataType != queryRopeDataType), OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
        "DataType of query rope(%s) is not equal to datatype of query(%s).",
        GetPfaDataTypeStr(queryRopeDataType).c_str(), GetPfaDataTypeStr(queryDataType).c_str()),
        return false);
    OP_CHECK_IF((keyDataType != keyRopeDataType), OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
        "DataType of key rope(%s) is not equal to datatype of key(%s).",
        GetPfaDataTypeStr(keyRopeDataType).c_str(), GetPfaDataTypeStr(keyDataType).c_str()),
        return false);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckKeyValueParamsConsistency(
    ContextParamsForPFATiling &contextKeyParams,
    const gert::StorageShape *keyShape,
    const gert::StorageShape *valueShape) 
{
  if (enableTensorList) {
    return true;
  }
  const size_t keyDimNum = keyShape->GetShape().GetDimNum();
  const size_t valueDimNum = valueShape->GetShape().GetDimNum();

  OP_CHECK_IF(keyDimNum != valueDimNum,
              OPS_REPORT_VECTOR_INNER_ERR(
                  contextKeyParams.opName,
                  "tensor key shape dimNum(%zu) must be consistent with tensor value shape dimNum(%zu)!",
                  keyDimNum,
                  valueDimNum),
              return false);
  OP_CHECK_IF((keyDimNum < INPUT_QKV_SHAPE_MIN_DIMS) || (keyDimNum > INPUT_QKV_SHAPE_MAX_DIMS),
              OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                          "tensor key shape dimNum(%zu) is invalid! Only support range [%u, %u].",
                                          keyDimNum,
                                          INPUT_QKV_SHAPE_MIN_DIMS,
                                          INPUT_QKV_SHAPE_MAX_DIMS),
              return false);
  for (uint32_t i = 0; i < keyDimNum; ++i) {
    if (((keyDimNum != KV_CACHE_DIM_NUMS_5 && i == keyDimNum - 1) ||
         (keyDimNum == KV_CACHE_DIM_NUMS_5 && i == KV_CACHE_DIM_2)) &&
        enablePFAMLA) { // 使能PFAMLA时，k和v的最后一维，或Nz时k和v的第三维允许不一致
      continue;
    }
    int64_t tmpKeyDim = keyShape->GetShape().GetDim(i);
    int64_t tmpValueDim = valueShape->GetShape().GetDim(i);

    OP_CHECK_IF(!isQKVDDifferent && (tmpKeyDim != tmpValueDim),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                            "tensor key shape(%ld) do not equal to tensor value shape(%ld) in dim %u.",
                                            tmpKeyDim,
                                            tmpValueDim,
                                            i),
                return false);
    OP_CHECK_IF(isQKVDDifferent && (i != keyDimNum - 1) && (tmpKeyDim != tmpValueDim),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
                                            "tensor key shape(%ld) do not equal to tensor value shape(%ld) in dim %u.",
                                            tmpKeyDim,
                                            tmpValueDim,
                                            i),
                return false);
  }
  return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckInputDimAndHeadNum(ContextParamsForPFATiling& contextKeyParams,
    const uint32_t nQAttr, const uint32_t nKVAttr) 
{
    uint32_t nQ = nQAttr;
    uint32_t nKV = nKVAttr;
    if (nKVAttr == 0U) { // Detected that nKVAttr is the default value, which means that the customer did not pass in.
        nKV = nQAttr;
    }

    const gert::StorageShape* queryShape = contextKeyParams.queryInputShape;
    const gert::StorageShape* keyShape = contextKeyParams.keyInputShape;
    const gert::StorageShape* valueShape = contextKeyParams.valueInputShape;
    uint32_t queryShapeHeadNum = nQ;
    uint32_t keyShapeHeadNum = nKV;
    uint32_t valueShapeHeadNum = nKV;
    const size_t queryDim = queryShape->GetStorageShape().GetDimNum();
    const size_t keyDim = keyShape->GetShape().GetDimNum();
    const size_t valueDim = valueShape->GetShape().GetDimNum();
    const size_t nIdx = (inputLayout == InputLayout::BNSD || inputLayout == InputLayout::TND) ? 1U : // BNSD/TND: 1
        (inputLayout == InputLayout::BSND) ? 2U : 0U; //  BSND:2; NTD:0

    if (((inputLayout == InputLayout::BNSD) || (inputLayout == InputLayout::BSND)) && (!enablePA)) {
      if ((static_cast<size_t>(queryDim) == 4U) && (static_cast<size_t>(keyDim) == 4U) &&
          (static_cast<size_t>(valueDim) == 4U)) { // dim num: 4
        queryShapeHeadNum = queryShape->GetStorageShape().GetDim(nIdx);
        keyShapeHeadNum = keyShape->GetShape().GetDim(nIdx);
        valueShapeHeadNum = valueShape->GetShape().GetDim(nIdx);
      } else {
        OP_LOGE(contextKeyParams.opName,
                "input dim of q(%zu), k(%zu), v(%zu) must be 4 for BNSD or BSND format!",
                queryDim,
                keyDim,
                valueDim);
        return false;
      }
    } else if ((inputLayout == InputLayout::TND) && (!enablePA)) {
      if ((static_cast<size_t>(queryDim) == 3U) && (static_cast<size_t>(keyDim) == 3U) &&
          (static_cast<size_t>(valueDim) == 3U)) { // dim num: 3
        queryShapeHeadNum = queryShape->GetStorageShape().GetDim(nIdx);
        keyShapeHeadNum = keyShape->GetShape().GetDim(nIdx);
        valueShapeHeadNum = valueShape->GetShape().GetDim(nIdx);
      } else {
        OP_LOGE(contextKeyParams.opName,
                "input dim of q(%zu), k(%zu), v(%zu) must be 3 for TND format!",
                queryDim,
                keyDim,
                valueDim);
        return false;
      }
    } else if ((inputLayout == InputLayout::NTD) && (!enablePA)) {
      if ((static_cast<size_t>(queryDim) == 3U) && (static_cast<size_t>(keyDim) == 3U) &&
          (static_cast<size_t>(valueDim) == 3U)) { // dim num: 3
        queryShapeHeadNum = queryShape->GetStorageShape().GetDim(nIdx);
        keyShapeHeadNum = keyShape->GetShape().GetDim(nIdx);
        valueShapeHeadNum = valueShape->GetShape().GetDim(nIdx);
      } else {
        OP_LOGE(contextKeyParams.opName,
                "input dim of q(%zu), k(%zu), v(%zu) must be 3 for NTD format!",
                queryDim,
                keyDim,
                valueDim);
        return false;
      }
    }

    OP_CHECK_IF(queryShapeHeadNum != nQ,
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
            "numHeads(%u) in query shape must be equal to numHeads(%u) in attr!", queryShapeHeadNum, nQ),
        return false);
    OP_CHECK_IF(keyShapeHeadNum != nKV,
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
            "numHeads(%u) in key shape do not match numKeyValueHeads(%u) in attr!", keyShapeHeadNum, nKV),
        return false);
    OP_CHECK_IF(valueShapeHeadNum != nKV,
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
            "numHeads(%u) in value shape do not match numKeyValueHeads(%u) in attr!", valueShapeHeadNum, nKV),
        return false);
    if (enableIFAMLA || enableIFA) {
        gSize = nQ / nKV;
    }
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::SetAndCheckHeadNumRatio(
    ContextParamsForPFATiling &contextKeyParams, PromptFlashAiInfraAttentionPioneerTilingData &tilingData) 
{
  const int32_t nQ = *contextKeyParams.headsNumber;
  const int32_t nKV = *contextKeyParams.numKeyValueHeads;

  if ((nQ < 0) || (nKV < 0)) {
    OP_LOGE(contextKeyParams.opName, "numHeads(%d) or numKeyValueHeads(%d) is negative!", nQ, nKV);
    return false;
  }

  if (!CheckInputDimAndHeadNum(contextKeyParams, nQ, nKV)) {
    return false;
  }

  if (nKV == 0) { // Detected that nKV is the default value, which means that the customer did not pass in.
    tilingData.promptAttentionBaseParams.set_headNumRatio(1);
    tilingData.promptAttentionBaseParams.set_gOfMla(1);
    return true;
  }

  if (nQ % nKV != 0) {
    OP_LOGE(contextKeyParams.opName, "numHeads(%d) must be divisible by numKeyValueHeads(%d)!", nQ, nKV);
    return false;
  }

  if (enableIFAMLA && (nQ / nKV > GLIMIT_128)) { // G cannot be greater than 128.
    OP_LOGE(contextKeyParams.opName,
            "In mla decode scenario, the G(numHeads / numKeyValueHeads) connot be larger than 128, but G = %d",
            nQ / nKV);
    return false;
  }

  if (enableIFAMLA || enableIFA) {
    tilingData.promptAttentionBaseParams.set_headNumRatio(1);
    tilingData.promptAttentionBaseParams.set_gOfMla(gSize);
  } else {
    tilingData.promptAttentionBaseParams.set_headNumRatio(nQ / nKV);
    tilingData.promptAttentionBaseParams.set_gOfMla(1);
  }

  return true;
}

void PromptFlashAiInfraAttentionPioneerTilingV2::SetSparseModeData(ContextParamsForPFATiling& contextKeyParams,
    const gert::StorageShape* attenMaskShape, const int32_t* sparseMode, const int64_t* preTokens,
    const int64_t* nextTokens) 
{
    if (*preTokens > SPARSE_MODE_INT_MAX) {
        sparsePreTokens = SPARSE_MODE_INT_MAX;
    } else if (*preTokens < -(SPARSE_MODE_INT_MAX)) {
        sparsePreTokens = -(SPARSE_MODE_INT_MAX);
    } else {
        sparsePreTokens = *preTokens;
    }

    if (*nextTokens > SPARSE_MODE_INT_MAX) {
        sparseNextTokens = SPARSE_MODE_INT_MAX;
    } else if (*nextTokens < -(SPARSE_MODE_INT_MAX)) {
        sparseNextTokens = -(SPARSE_MODE_INT_MAX);
    } else {
        sparseNextTokens = *nextTokens;
    }
    if ((attenMaskShape != nullptr) && (sparseMode != nullptr)) {
        if (*sparseMode == SPARSE_MODE_LEFT_UP) {
            sparsePreTokens = SPARSE_MODE_INT_MAX;
            sparseNextTokens = 0;
        // Right down tokens are calculated on the kernel side.
        } else if (*sparseMode == SPARSE_MODE_RIGHT_DOWN) {
            sparsePreTokens = SPARSE_MODE_INT_MAX;
        } else if (*sparseMode == SPARSE_MODE_ALL_MASK) {
            sparsePreTokens = SPARSE_MODE_INT_MAX;
            sparseNextTokens = SPARSE_MODE_INT_MAX;
        } else if (*sparseMode == SPARSE_MODE_BAND) {
            isBandMode = true;
        }
        sparseModeVal = *sparseMode;
        OP_LOGI(contextKeyParams.opName, "sparseMode is %d.", sparseModeVal);
    }
    if ((sparseMode != nullptr) && (*sparseMode == SPARSE_MODE_NO_MASK)) {
        // sparse mode need process attention mask when empty tensor scenes as same.
        if (((attenMaskShape != nullptr) && (attenMaskShape->GetStorageShape().GetShapeSize() == 0)) || 
            (attenMaskShape == nullptr)) {
            sparsePreTokens = SPARSE_MODE_INT_MAX;
            sparseNextTokens = SPARSE_MODE_INT_MAX;
            sparseModeVal = *sparseMode;
        }
    }
    if (isDefaultSparseMode && enableLeftPadding) {
        // For scenes with sparse mode=0 and left padding, the attention mask part is fully calculated
        sparsePreTokens = SPARSE_MODE_INT_MAX;
        sparseNextTokens = SPARSE_MODE_INT_MAX;
    }
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckMaskShapeCrossSparse(ContextParamsForPFATiling& contextKeyParams,
    PromptFlashAiInfraAttentionPioneerTilingData& tilingData, const int32_t* sparseMode, uint32_t sQ, const uint32_t sK,
    const uint32_t batchSize) 
{
    const gert::StorageShape* attenMaskShape = contextKeyParams.attentionMaskShape;
    size_t attenMaskDim = attenMaskShape->GetStorageShape().GetDimNum();
    if (static_cast<size_t>(attenMaskDim) != 2U) {
        return false;
    }
    int64_t attenMaskS1 = attenMaskShape->GetStorageShape().GetDim(0);
    int64_t attenMaskS2 = attenMaskShape->GetStorageShape().GetDim(1);
    if (attenMaskS1 != 2048 || attenMaskS2 != 2048) {
        return false;
    }
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckPFAMerge(ContextParamsForPFATiling& contextKeyParams,
    const PFAShapeInfo& queryShapeInfo) const 
{
    const int32_t pfaMergeGSLimit = pfaMergeQsLimit * pfaMergeGLimit;

    if (queryShapeInfo.s <= 1U) {
        return false;
    }

    if (queryShapeInfo.d > 256U &&
        (queryShapeInfo.d % 64) != 0) { // 256U, 64: d > 256 must be multiple of 64 for memory alignment
      return false;
    }

    const int32_t nQ = *contextKeyParams.headsNumber;
    const int32_t nKV = *contextKeyParams.numKeyValueHeads;
    if ((nKV > 0) && (static_cast<uint32_t>(nQ / nKV) * queryShapeInfo.s > pfaMergeGSLimit)) {
        return false;
    }
    if ((nKV == 0) && (queryShapeInfo.s > pfaMergeGSLimit)) {
        return false;
    }

    // 隔离高阶特性
    std::string layoutStr(contextKeyParams.layout);
    bool isTransposeLayout = layoutStr == "BNSD_BSND" || layoutStr == "BSND_BNSD" || layoutStr == "BSH_BNSD" ||
        layoutStr == "NTD" || layoutStr == "NTD_TND" || layoutStr == "TND_NTD";
    bool hasCrossoverAttr = enableMask || enablePseShift || enablePA || enableAlibiPse || enablePFARope ||
        enableLeftPadding || enableTensorList ||
        contextKeyParams.isSoftMaxLseEnable || isTransposeLayout || enableLearnSink;

    return !hasCrossoverAttr;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckIO(ContextParamsForPFATiling& contextKeyParams,
    PFAShapeInfo& queryShapeInfo, PFAShapeInfo& valueShapeInfo) 
{
    const gert::StorageShape* queryShape = contextKeyParams.queryInputShape;
    const gert::StorageShape* outShape = contextKeyParams.outputShape;
    const gert::StorageShape* valueShape = contextKeyParams.valueInputShape;
    // check dtype
    if (!CheckIODataType(contextKeyParams)) {
        return false;
    }

    // check layout
    OP_CHECK_IF((!SetInputLayout(contextKeyParams.layout)),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, 
            "Invalid input layout:%s. Only TND and TND_NTD are supported for attention pioneer.",
            contextKeyParams.layout),
        return false);

    // check query shape size and bnsd
    OP_CHECK_IF((!GetAndCheckShape(contextKeyParams, queryShapeInfo, queryShape, "query")),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check query shape failed."),
        return false);
    if (queryShapeInfo.s == 1) {
        enableIFAMask = true;
        enableIFA = true;
    }
    enablePFAMerge = CheckPFAMerge(contextKeyParams, queryShapeInfo);
    // check value shape
    if (enablePA) { // only get shape
        int64_t b = 0;
        int64_t n = 0;
        int64_t s = 0;
        int64_t d = 0;
        int64_t h = 0;
        int64_t t = 0;
        if (!SetShape(contextKeyParams, valueShape, "value", b, n, s, d, h, t)) {
            return false;
        }
        valueShapeInfo.d = d;
    } else {
        OP_CHECK_IF((!GetAndCheckShape(contextKeyParams, valueShapeInfo, valueShape, "value")),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check value shape failed."),
        return false);
    }
    if (queryShapeInfo.d == MLA_QKD_SIZE && valueShapeInfo.d == MLA_VD_SIZE) {
        enablePFAMLA = true;
        enablePFAMerge = false;
    }

    if(queryShapeInfo.d != valueShapeInfo.d && !enablePFAMLA) {
        isQKVDDifferent = true;
    }
    OP_CHECK_IF(
        isQKVDDifferent &&
            (contextKeyParams.inputDataType != ge::DT_FLOAT16 && contextKeyParams.inputDataType != ge::DT_BF16),
        OPS_REPORT_VECTOR_INNER_ERR(
            contextKeyParams.opName,
            "Query data type must be float16 or bf16 when query and key headdim is not equal to value headdim."),
        return false);
    OP_CHECK_IF(
        isQKVDDifferent && (outputType != ge::DT_FLOAT16 && outputType != ge::DT_BF16),
        OPS_REPORT_VECTOR_INNER_ERR(
            contextKeyParams.opName,
            "Output data type must be float16 or bf16 when query and key headdim is not equal to value headdim."),
        return false);
    OP_CHECK_IF(isQKVDDifferent && (queryShapeInfo.d > 128),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "Query headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
                return false);
    OP_CHECK_IF(isQKVDDifferent && (valueShapeInfo.d > 128),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "Value headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
                return false);
    // check query and output consistency
    OP_CHECK_IF((!CheckQueryOutParamsConsistency(contextKeyParams, queryShape, outShape)),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Query and output consistency check failed."),
        return false);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckKV(ContextParamsForPFATiling& contextKeyParams,
    PFAShapeInfo& keyShapeInfo, PFAShapeInfo& valueShapeInfo) 
{
    const gert::StorageShape* keyShape = contextKeyParams.keyInputShape;
    const gert::StorageShape* valueShape = contextKeyParams.valueInputShape;

    // check dtype
    if (!CheckKVDataType(contextKeyParams)) {
        return false;
    }

    // check key shape size and bnsd
    OP_CHECK_IF((!enablePA && !GetAndCheckShape(contextKeyParams, keyShapeInfo, keyShape, "key")),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check key shape failed."),
        return false);

    // check value shape size and bnsd
    OP_CHECK_IF((!enablePA && !GetAndCheckShape(contextKeyParams, valueShapeInfo, valueShape, "value")),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check value shape failed."),
        return false);

    OP_CHECK_IF(isQKVDDifferent &&
                    (contextKeyParams.kDataType != ge::DT_FLOAT16 && contextKeyParams.kDataType != ge::DT_BF16),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "Key type must must be float16 or bf16 when query and key headdim is not equal to value headdim."),
                return false);
    OP_CHECK_IF(
        isQKVDDifferent && (contextKeyParams.vDataType != ge::DT_FLOAT16 && contextKeyParams.vDataType != ge::DT_BF16),
        OPS_REPORT_VECTOR_INNER_ERR(
            contextKeyParams.opName,
            "Value type must must be float16 or bf16 when query and key headdim is not equal to value headdim."),
        return false);
    OP_CHECK_IF(isQKVDDifferent && (keyShapeInfo.d > 128),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "Key headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
                return false);
    OP_CHECK_IF(isQKVDDifferent && (valueShapeInfo.d > 128),
                OPS_REPORT_VECTOR_INNER_ERR(
                    contextKeyParams.opName,
                    "Value headdim must smaller than 128 when query and key headdim is not equal to value headdim."),
                return false);
    // check key and value consistency
    OP_CHECK_IF((!CheckKeyValueParamsConsistency(contextKeyParams, keyShape, valueShape)),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Key and value consistency check failed."),
        return false);

    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckQueryAndKey(ContextParamsForPFATiling& contextKeyParams,
    PFAShapeInfo& queryShapeInfo, PFAShapeInfo& keyShapeInfo, PromptFlashAiInfraAttentionPioneerTilingData& tilingData) 
{
    // check numhead ratio
    if (!SetAndCheckHeadNumRatio(contextKeyParams, tilingData)) {
        return false;
    }

    return true;
}


bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckRope(ContextParamsForPFATiling& contextKeyParams,
    PFAShapeInfo& queryShapeInfo, PFAShapeInfo& keyShapeInfo, PFAShapeInfo& queryRopeShapeInfo) 
{
    if (contextKeyParams.queryRopeInputShape == nullptr && contextKeyParams.keyRopeInputShape == nullptr) {
        return true;
    }
    OP_CHECK_IF((contextKeyParams.queryRopeInputShape == nullptr && contextKeyParams.keyRopeInputShape != nullptr),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "queryRope is null, but keyRope is not null, "
        "they should be consistent."), return false);
    OP_CHECK_IF((contextKeyParams.queryRopeInputShape != nullptr && contextKeyParams.keyRopeInputShape == nullptr),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "queryRope is not null, but keyRope is null, "
        "they should be consistent."), return false);
    OP_CHECK_IF(!(CheckRopeDataType(contextKeyParams)),
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Check rope datatype failed."),
        return false);
    const gert::StorageShape* queryRopeShape = contextKeyParams.queryRopeInputShape;
    const gert::StorageShape* keyRopeShape = contextKeyParams.keyRopeInputShape;

    // check queryRope shape
    OP_CHECK_IF((!GetAndCheckRopeShape(
                    contextKeyParams, queryShapeInfo, queryRopeShapeInfo, queryRopeShape, "query", "queryRope")),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check queryRope shape failed."),
                return false);
    // check keyRope shape
    PFAShapeInfo keyRopeShapeInfo;
    OP_CHECK_IF((!enablePA && !GetAndCheckRopeShape(
                                  contextKeyParams, keyShapeInfo, keyRopeShapeInfo, keyRopeShape, "key", "keyRope")),
                OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName, "Get and check queryRope shape failed."),
                return false);
    enableIFA = false;
    enableIFAMask = false;
    enablePFAMerge = false;
    if (queryShapeInfo.d == QUERY_SHAPE_DIM_D_128_TILING_V2) {
        enablePFARope = true;
    } else {
        enableIFAMLA = true;
    }
    OP_LOGI(contextKeyParams.opName, "enableIFAMLA is %d, enablePA is %d, enableMask is %d, faRunFlag_ is %d", 
                enableIFAMLA, enablePA, enableMask, faRunFlag_);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckLayout(ContextParamsForPFATiling& contextKeyParams) const
{
    if (contextKeyParams.layout == nullptr) {
        return false;
    }
    std::string layoutStr(contextKeyParams.layout);
    bool validLayout = (layoutStr == "TND") || (layoutStr == "TND_NTD");
    OP_CHECK_IF(!validLayout,
        OP_LOGE(contextKeyParams.opName, "Only TND and TND_NTD layouts are supported, but got %s", layoutStr.c_str()),
        return false);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckQuant(ContextParamsForPFATiling& contextKeyParams,
    PFAShapeInfo& queryShapeInfo, PFAShapeInfo& keyShapeInfo, const PFAShapeInfo& valueShapeInfo) const
{
    // Sink attention pioneer does not support quantization features
    OP_CHECK_IF(enablePertensorQuant || enablePerblockQuant || enablePostQuant || enableKVAntiquant,
        OPS_REPORT_VECTOR_INNER_ERR(contextKeyParams.opName,
            "Quantization (per-tensor, per-block, post-quant, antiquant) is not supported for sink attention pioneer."),
        return false);
    return true;
}

bool PromptFlashAiInfraAttentionPioneerTilingV2::CheckPrefix(ContextParamsForPFATiling& contextKeyParams,
    const PFAShapeInfo& queryShapeInfo, PFAShapeInfo& keyShapeInfo,
    PromptFlashAiInfraAttentionPioneerTilingData& tilingData)
{
    tilingData.promptAttentionBaseParams.set_prefixSeqInnerSize(0);
    if (!isKVHasPrefix) {
        tilingData.promptAttentionBaseParams.set_isActualSharedPrefixLenNull(1);
        actualSharedPrefixLen = 0;
        return true;
    }

