aclnnStatus aclnnAiInfraAttentionPioneer(void *workspace, uint64_t workspaceSize, aclOpExecutor *executor,
                                          const aclrtStream stream);

#ifdef __cplusplus
}
#endif

#endif // OP_API_INC_LEVEL2_ACLNN_AI_INFRA_ATTENTION_PIONEER_H_

