3515	void PromptFlashAiInfraAttentionPioneerTilingV2::InitializeMaxWorkspace(PFAShapeInfo& queryShapeInfo,
3516	    PFAShapeInfo& keyShapeInfo, std::vector<int64_t>& actualSeqLengths, std::vector<int64_t>& actualSeqLengthsKV) 
3517	{
3518	    uint32_t lenDims = queryShapeInfo.b;
3519	    for (uint32_t i = LOOP_BEGIN_NUM; i < lenDims; i++) {
3520	        actualSeqLengths[i] = queryShapeInfo.s;
