3525	
3526	ge::graphStatus PromptFlashAiInfraAttentionPioneerTilingV2::RunBigKernelTilingWithParams(
3527	    ContextParamsForPFATiling &contextKeyParams,
3528	    uint32_t &numBlocksToBeSet,
3529	    PromptFlashAiInfraAttentionPioneerTilingData &tilingData) 
3530	{
3531	  GetMaxWorkspaceFlag(contextKeyParams);
3532	
3533	  // set memory parameters
3534	  if (SetPlatMemoryInfo(contextKeyParams) != ge::GRAPH_SUCCESS) {
3535	    return ge::GRAPH_FAILED;
3536	  }
3537	  // set sttributes switch
3538	  if (SetAttributeInfo(contextKeyParams) != ge::GRAPH_SUCCESS) {
3539	    return ge::GRAPH_FAILED;
3540	  }
3541	  // tensor ptr is empty or tensor is invalid
3542	  if (CheckTensorInvalid(contextKeyParams) != ge::GRAPH_SUCCESS) {
3543	    return ge::GRAPH_FAILED;
3544	  }
3545	
3546	  // empty tensor check
3547	  if (CheckEmptyTensor(contextKeyParams) != ge::GRAPH_SUCCESS) {
3548	    return ge::GRAPH_FAILED;
3549	  }
3550	  if (emptyTensor) {
3551	    SetEmptyTensor(contextKeyParams, numBlocksToBeSet, tilingData);
3552	    return ge::GRAPH_SUCCESS;
3553	  }
3554	
3555	  // Input, output check
3556	  PFAShapeInfo queryShapeInfo;
3557	  PFAShapeInfo keyShapeInfo;
3558	  PFAShapeInfo valueShapeInfo;
3559	  PFAShapeInfo queryRopeShapeInfo;
3560	
3561	  // Check kinds of single attribute
3562	  if (CheckSingleAttribute(
3563	          contextKeyParams, queryShapeInfo, keyShapeInfo, valueShapeInfo, queryRopeShapeInfo, tilingData) !=
3564	      ge::GRAPH_SUCCESS) {
3565	    return ge::GRAPH_FAILED;
3566	  }
3567	  // 同IFA合轴实现
3568	  if (enablePFAMerge) {
3569	    if (*contextKeyParams.numKeyValueHeads > 0) {
3570	      gSize = (*contextKeyParams.headsNumber) / (*contextKeyParams.numKeyValueHeads);
3571	    } else {
3572	      gSize = 1U;
3573	    }
3574	    tilingData.promptAttentionBaseParams.set_headNumRatio(1);
3575	    tilingData.promptAttentionBaseParams.set_gOfMla(gSize);
3576	  }
3577	  OP_CHECK_IF(
3578	      gSize == 0, OPS_REPORT_VECTOR_INNER_ERR(context_->GetNodeName(), "calculate gSize = 0"), return ge::GRAPH_FAILED);
3579	
3580	  if (enableIFAMLA || enableIFA || enablePFAMerge) {
3581	    queryShapeInfo.n = queryShapeInfo.n / gSize;
3582	    queryShapeInfo.s = queryShapeInfo.s * gSize;
3583	  }
3584	
3585	  // multi feature crossover check
3586	  std::vector<int64_t> actualSeqLengths(queryShapeInfo.b);
3587	  std::vector<int64_t> actualSeqLengthsKV(queryShapeInfo.b);
3588	
3589	  // Check crossover attribute
3590	  if (CheckCrossoverAttribute(contextKeyParams, queryShapeInfo, tilingData) != ge::GRAPH_SUCCESS) {
3591	    return ge::GRAPH_FAILED;
3592	  }
3593	
3594	  InitializeMaxWorkspace(queryShapeInfo, keyShapeInfo, actualSeqLengths, actualSeqLengthsKV);
3595	  needInit = 1;
3596	
3597	  // print shape info
3598	  OP_LOGI(contextKeyParams.opName,
3599	          "inputLayout is %s, innerPrecise is %d, scaleValue is %f, preTokens is %ld, nextTokens is %ld",
3600	          string(contextKeyParams.layout).c_str(),
3601	          innerPrecise,
3602	          *contextKeyParams.scaleValue,
3603	          *contextKeyParams.preToken,
3604	          *contextKeyParams.nextToken);
3605	
3606	  // set tilingData
3607	  SetTilingData(contextKeyParams, queryShapeInfo, queryRopeShapeInfo, valueShapeInfo, tilingData);
3608	
3609	  // Infering whether the tiling mode is S2 full load, CV diff, and whether to use the matmul norm template.
3610	  InferTilingMod(contextKeyParams, actualSeqLengths, actualSeqLengthsKV, queryShapeInfo.b, queryShapeInfo.d);
3611	  InferSplitCoreMode();
3612	  // Whether to enable constant templates
3613	  InferConstantization();
3614	
3615	  if (AdjustTilingData(contextKeyParams, tilingData, queryShapeInfo) != ge::GRAPH_SUCCESS) {
3616	    return ge::GRAPH_FAILED;
3617	  }
3618	
3619	  // DN check
3620	  GetEnableDN(contextKeyParams, tilingData, queryShapeInfo, valueShapeInfo, actualSeqLengths, actualSeqLengthsKV);
3621	
3622	  if (ComputeTilingData(contextKeyParams, actualSeqLengths, actualSeqLengthsKV, tilingData) != ge::GRAPH_SUCCESS) {
3623	    return ge::GRAPH_FAILED;
3624	  }
3625	
3626	  // Compute tiling key.
3627	  if (ComputeTilingKey(contextKeyParams, numBlocksToBeSet, tilingData) != ge::GRAPH_SUCCESS) {
3628	    return ge::GRAPH_FAILED;
3629	  }
3630	
3631	  if (SetQKVStartIdx(contextKeyParams) != ge::GRAPH_SUCCESS) {
3632	    return ge::GRAPH_FAILED;
