#ifndef AI_INFRA_ATTENTION_PIONEER_KERNEL_NOQUANT_MLA_H_
#define AI_INFRA_ATTENTION_PIONEER_KERNEL_NOQUANT_MLA_H_

#include "../../common/op_kernel/arch35/attenmask.h"
