536	        return;
537	    }
538	
539	    // 确定核内切分起点
540	    int64_t gS1StartIdx = 0;
541	    int64_t gS1EndIdx = 1;
542	    uint32_t bnStartIdx = 0;
543	    uint32_t bnEndIdx = 1;
544	    int64_t s2LoopStart = 0;
545	    int64_t s2LoopLimit = 0;
546	    int64_t nextGs1Idx = this->tilingData->multiCoreParamsRegbase.sparseStartIdx[aicIdx + 1];
547	    if constexpr (!isFd) {
548	        bnStartIdx = this->tilingData->multiCoreParamsRegbase.bnStartIdx[aicIdx];
549	        gS1StartIdx = this->tilingData->multiCoreParamsRegbase.sparseStartIdx[aicIdx];
550	        if (likely((this->tilingData->multiCoreParamsRegbase.coreNum - 1) > aicIdx)) {
551	            bnEndIdx = this->tilingData->multiCoreParamsRegbase.bnStartIdx[aicIdx + 1];
552	            // 下一个核从0开始gs1循环，当前核bn不需要多计算一个，否则需要多计算一个bn
553	            if (this->tilingData->multiCoreParamsRegbase.sparseStartIdx[aicIdx + 1] != 0) {
554	                bnEndIdx++;
555	            }
556	        } else {
557	            bnEndIdx = this->tilingData->inputParamsRegbase.bSize * constInfo.n2Size;
558	            nextGs1Idx = 0;
559	        }
560	    }
561	    int64_t taskId = 0;
562	    bool isLastBmm1 = false;
563	    RunInfo<isInfer> runInfo[NUM_4];
564	    RunParamStr<isInfer> runParam;
565	
566	    if constexpr (isFd) {
567	        runParam.boIdx = aicIdx / (constInfo.n2Size * constInfo.splitKVNum);
568	        runParam.n2oIdx = (aicIdx / constInfo.splitKVNum) % constInfo.n2Size;
569	        bnStartIdx = runParam.boIdx * constInfo.n2Size + runParam.n2oIdx;
570	        bnEndIdx = bnStartIdx + 1;
571	    }
572	
573	    int64_t multiCoreInnerIdx = 0;
574	    constInfo.sinkBlockCnt = (constInfo.sinkLength + s2BaseSize - 1) / s2BaseSize;
