577	        bool lastBN = IsLastBN(bnIdx, bnEndIdx);
578	        if constexpr (!isFd) {
579	            runParam.boIdx = bnIdx / constInfo.n2Size;
580	            runParam.n2oIdx = bnIdx % constInfo.n2Size;
581	        }
