585	            nextGs1Idx);
586	        if constexpr (isFd) {
587	            if (constInfo.sInnerLoopSize * (aicIdx % constInfo.splitKVNum) > runParam.actualSeqLengthKVPerBatch) {
588	                runParam.actualSInnerLoopSize = 0;
589	            } else {
590	                int64_t tailSInnerLoopSize =
591	                    runParam.actualSeqLengthKVPerBatch - constInfo.sInnerLoopSize * (aicIdx % constInfo.splitKVNum);
592	                runParam.actualSInnerLoopSize =
593	                    tailSInnerLoopSize > constInfo.sInnerLoopSize ? constInfo.sInnerLoopSize : tailSInnerLoopSize;
594	            }
595	            runParam.s1LoopTimes = 1; // GQA支持后解决
596	        }
597	        if (unlikely(lastBN && runParam.s1LoopTimes == 0)) {
598	            if (taskId >= PRELOAD_N) {
599	                RunInfo<isInfer> &runInfo2 = runInfo[(taskId - PRELOAD_N) & 3];
600	                if ASCEND_IS_AIC {
601	                    this->cubeBlock.IterateBmm2(this->bmm2Buffers.Get(), runInfo2, constInfo);
602	                }
603	                if ASCEND_IS_AIV {
604	                    this->vecBlock.ProcessVec2(this->bmm2Buffers.Get(), runInfo2, this->constInfo);
605	                }
606	            }
607	        }
608	        gS1EndIdx = runParam.s1LoopTimes;
609	        for (int64_t gS1Index = gS1StartIdx; gS1Index < runParam.s1LoopTimes; gS1Index++) {
610	            s2LoopLimit = 0;
611	            this->ComputeAxisIdxByBnAndGs1(bnIdx, gS1Index, multiCoreInnerIdx, runParam);
612	            bool s1NoNeedCalc = ComputeParamS1<CHILD_SPEC_TEMPLATE_ARGS, useDn, enableKVPrefix>(runParam, constInfo,
613	                gS1Index, actualSeqQlenAddr, this->pseInfo);
614	            bool s2NoNeedCalc = ComputeS2LoopInfo<CHILD_SPEC_TEMPLATE_ARGS, useDn, enableKVPrefix>(runParam, constInfo);
615	            bool lastLoopThisCore = lastBN && (gS1Index == runParam.s1LoopTimes - 1);
616	            bool lastBnNoNeedCalc = ComputeLastBN<CHILD_SPEC_TEMPLATE_ARGS, useDn, enableKVPrefix>(runParam,
617	                actualSeqQlenAddr);
618	            if (((s1NoNeedCalc || s2NoNeedCalc) && !lastLoopThisCore) || lastBnNoNeedCalc) {
619	                continue;
620	            }
621	            // s2轴循环计数，支持sparse和非sparse场景
622	            if (runParam.s2LoopEndIdx != 0) {
623	                // 加上sink部分的主流程循环次数 runParam.s2LoopEndIdx 保持含义：当前行需要计算的S2loop次数
624	                runParam.s2LoopEndIdx += constInfo.sinkBlockCnt;
