628	                isLastBmm1 = true;
629	                s2LoopLimit += PRELOAD_N;
630	            }
631	            for (int64_t s2LoopCount = 0; s2LoopCount <= s2LoopLimit; s2LoopCount++) {
632	                if (s2LoopCount < runParam.s2LoopEndIdx) {
633	                    RunInfo<isInfer> &runInfo1 = runInfo[taskId & 3];
634	                    this->SetRunInfo(runInfo1, runParam, taskId, s2LoopCount, runParam.s2LoopEndIdx - 1,
635	                        multiCoreInnerIdx);
636	                    if ASCEND_IS_AIC {
637	                        this->cubeBlock.IterateBmm1(this->bmm1Buffers.Get(), runInfo1, runParam, isLastBmm1 &&
638	                            (s2LoopCount == (runParam.s2LoopEndIdx - 1)), constInfo);
639	                    }
640	                    if ASCEND_IS_AIV {
641	                        this->vecBlock.ProcessVec1(this->mm12Bmm2AL1Buffers.Get(), this->bmm1Buffers.Get(), runInfo1,
