643	                    }
644	                }
645	                if (taskId >= PRELOAD_N) {
646	                    RunInfo<isInfer> &runInfo2 = runInfo[(taskId - PRELOAD_N) & 3];
647	                    if ASCEND_IS_AIC {
648	                        this->cubeBlock.IterateBmm2(this->bmm2Buffers.Get(), runInfo2, constInfo);
649	                    }
650	                    if ASCEND_IS_AIV {
651	                        this->vecBlock.ProcessVec2(this->bmm2Buffers.Get(), runInfo2, this->constInfo);
652	                    }
653	                }
654	                taskId++;
655	            }
656	        }
657	        gS1StartIdx = 0;
658	    }
659	
660	    if constexpr (isFd) {
661	        if ASCEND_IS_AIV {
662	            SyncAll();
663	            this->vecBlock.InitFDBuffers(this->constInfo);
664	            this->vecBlock.FlashDecodeCompute(this->constInfo, this->keyGm, this->actualSeqKvlenAddr);
665	        }
666	    }
