/*!
 * \file ap_metadata_defs.h
 * \brief Metadata layout constants for ai_infra_attention_pioneer split-core scheduling.
 *        Mirrors the layout defined in ai_infra_attention_pioneer_metadata, kept local
 *        to avoid cross-operator includes.
 */

#ifndef AP_METADATA_DEFS_H_
#define AP_METADATA_DEFS_H_

namespace ap_metadata {

constexpr uint32_t AIC_CORE_NUM = 36;
constexpr uint32_t SLOTS_PER_CORE = 10;
constexpr uint32_t BASE_OFFSET = AIC_CORE_NUM * SLOTS_PER_CORE;  // 360

// Per-core field indices (mirror PerCoreField in optiling)
enum class PerCoreField : uint32_t {
    AIC_CORE_ENABLE = 0,
    BN2_START_PTR   = 1,
    GS1_START_PTR   = 2,
    // indices 3..9 reserved
    K_COUNT         = SLOTS_PER_CORE,
};

// Base metadata field indices (mirror BaseMetaField in optiling)
enum class BaseMetaField : uint32_t {
    USED_CORE_NUM                 = 0,
    M_BASE_SIZE                   = 1,
    S_INNER_SIZE                  = 2,
    S1_OUTER_SIZE                 = 3,
    S1_SIZE                       = 4,
    S2_SIZE                       = 5,
    ACTUAL_LEN_Q_DIM              = 6,
    ACTUAL_LEN_KV_DIM             = 7,
    MULTI_SMAX_S_INNER_LOOP_TIMES = 8,
    ACTUAL_CORE_NUMS              = 9,
    TOTAL_SIZE                    = 10,
    SPLIT_FACTOR_SIZE             = 11,
    SPLIT_FACTOR_TAIL_SIZE        = 12,
    T1_SIZE                       = 13,
    T2_SIZE                       = 14,
    NEED_INIT                     = 15,
    K_COUNT,                             // === 16
};

constexpr uint32_t BASE_METADATA_SIZE = static_cast<uint32_t>(BaseMetaField::K_COUNT);

__aicore__ inline constexpr uint32_t GetCoreFieldOffset(uint32_t coreIdx, PerCoreField field)
{
    return coreIdx * SLOTS_PER_CORE + static_cast<uint32_t>(field);
}

__aicore__ inline constexpr uint32_t GetBaseMetaIndex(BaseMetaField field)
{
    return BASE_OFFSET + static_cast<uint32_t>(field);
}

} // namespace ap_metadata

#endif // AP_METADATA_DEFS_H_

