__aicore__ inline void FAKernelNoquantMla<CubeBlockType, VecBlockType>::ReadMetadataForSplitCore()
{
    // Read base metadata scalars from device-side metadata tensor
    auto &mcParams = const_cast<MultiCoreParamsRegbase &>(this->tilingData->multiCoreParamsRegbase);
    auto &inputParams = const_cast<InputParamsRegbase &>(this->tilingData->inputParamsRegbase);
    auto &initOutput = const_cast<InitOutputParams &>(this->tilingData->initOutputParams);
    const __gm__ int32_t *metaPtr = this->metadataGm.GetPhyAddr();

    uint32_t usedCoreNum =
        static_cast<uint32_t>(metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::USED_CORE_NUM)]);
    uint32_t s1OuterSize =
        static_cast<uint32_t>(metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::S1_OUTER_SIZE)]);
    int32_t totalSize = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::TOTAL_SIZE)];
    int32_t splitFactorSize = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::SPLIT_FACTOR_SIZE)];
    int32_t splitFactorTailSize =
        metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::SPLIT_FACTOR_TAIL_SIZE)];

    // Read s1Size, s2Size, t1Size, t2Size from metadata (depend on device-side actual_seq_lengths)
    int32_t s1Size = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::S1_SIZE)];
    int32_t s2Size = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::S2_SIZE)];
    int32_t t1Size = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::T1_SIZE)];
    int32_t t2Size = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::T2_SIZE)];
    int32_t needInit = metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::NEED_INIT)];

    // Set multiCoreParamsRegbase scalar fields
    mcParams.coreNum = static_cast<int32_t>(usedCoreNum);
    mcParams.s1OuterSize = static_cast<int64_t>(s1OuterSize);
    mcParams.totalSize = static_cast<int64_t>(totalSize);
    mcParams.splitFactorSize = static_cast<int64_t>(splitFactorSize);
    mcParams.splitFactorTailSize = static_cast<int64_t>(splitFactorTailSize);

    // Overwrite inputParamsRegbase fields that depend on device-side actual_seq_lengths
    inputParams.s1Size = static_cast<uint32_t>(s1Size);
    inputParams.s2Size = static_cast<uint32_t>(s2Size);
    inputParams.t2Size = static_cast<int64_t>(t2Size);
    inputParams.actualSeqLengthsSize = static_cast<uint32_t>(
        metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::ACTUAL_LEN_Q_DIM)]);
    inputParams.actualSeqLengthsKVSize = static_cast<uint32_t>(
        metaPtr[ap_metadata::GetBaseMetaIndex(ap_metadata::BaseMetaField::ACTUAL_LEN_KV_DIM)]);
    if (t1Size != inputParams.t1Size) {
        needInit = 1;
    }
    initOutput.needInit = needInit;

    // Copy per-core bnStartIdx and sparseStartIdx from metadata
    // Read up to usedCoreNum + 1 to include the end boundary (kernel accesses [aicIdx + 1])
    uint32_t boundaryCount = (usedCoreNum < ap_metadata::AIC_CORE_NUM) ? (usedCoreNum) : usedCoreNum;
    for (uint32_t i = 0; i < boundaryCount && i < ap_metadata::AIC_CORE_NUM; i++) {
      mcParams.bnStartIdx[i] =
          static_cast<uint32_t>(metaPtr[ap_metadata::GetCoreFieldOffset(i, ap_metadata::PerCoreField::BN2_START_PTR)]);
      mcParams.sparseStartIdx[i] =
          static_cast<int64_t>(metaPtr[ap_metadata::GetCoreFieldOffset(i, ap_metadata::PerCoreField::GS1_START_PTR)]);
    }
}

